/* The Readings Library, group celt (GWG BLD 798). Written by build-readings.py; edit the data, then build again. */
(window.GGReadingsData = window.GGReadingsData || {})["celt"] = [{"id":"celt-deers-cry","title":"The Deer's Cry (Saint Patrick's Breastplate)","by":"Attributed to Saint Patrick","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["morning","blessing","daily","hope"],"text":"I arise to-day\nThrough a mighty strength, the invocation of the Trinity,\nThrough belief in the threeness,\nThrough confession of the oneness\nOf the Creator of Creation.\n\nI arise to-day\nThrough the strength of Christ's birth with His baptism,\nThrough the strength of His crucifixion with His burial,\nThrough the strength of His resurrection with His ascension,\nThrough the strength of His descent for the judgment of Doom.\n\nI arise to-day\nThrough the strength of the love of Cherubim,\nIn obedience of angels,\nIn the service of archangels,\nIn hope of resurrection to meet with reward,\nIn prayers of patriarchs,\nIn predictions of prophets,\nIn preachings of apostles,\nIn faiths of confessors,\nIn innocence of holy virgins,\nIn deeds of righteous men.\n\nI arise to-day\nThrough the strength of heaven:\nLight of sun,\nRadiance of moon,\nSplendour of fire,\nSpeed of lightning,\nSwiftness of wind,\nDepth of sea,\nStability of earth,\nFirmness of rock.\n\nI arise to day\nThrough God's strength to pilot me:\nGod's might to uphold me,\nGod's wisdom to guide me,\nGod's eye to look before me,\nGod's ear to hear me,\nGod's word to speak for me,\nGod's hand to guard me,\nGod's way to lie before me,\nGod's shield to protect me,\nGod's host to save me\nFrom snares of devils,\nFrom temptations of vices,\nFrom every one who shall wish me ill,\nAfar and anear,\nAlone and in a multitude.\n\nI summon to-day all these powers between me and those evils,\nAgainst every cruel merciless power that may oppose my body and soul,\nAgainst incantations of false prophets,\nAgainst black laws of pagandom,\nAgainst false laws of heretics,\nAgainst craft of idolatry,\nAgainst spells of women and smiths and wizards,\nAgainst every knowledge that corrupts man's body and soul.\n\nChrist to shield me to-day\nAgainst poison, against burning,\nAgainst drowning, against wounding,\nSo that there may come to me abundance of reward.\nChrist with me, Christ before me, Christ behind me,\nChrist in me, Christ beneath me, Christ above me,\nChrist on my right, Christ on my left,\nChrist when I lie down, Christ when I sit down, Christ when I arise,\nChrist in the heart of every man who thinks of me,\nChrist in the mouth of every one who speaks of me,\nChrist in every eye that sees me,\nChrist in every ear that hears me.\n\nI arise to-day\nThrough a mighty strength, the invocation of the Trinity,\nThrough belief in the threeness,\nThrough confession of the oneness\nOf the Creator of Creation.","note":"The old Irish lorica, prayed for protection at the start of a day or a journey; tradition says Patrick sang it on the road to Tara.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-even-song","title":"An Even-Song","by":"Attributed to Saint Patrick","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["evening","peace"],"text":"May Thy holy angels, O Christ, son of living God,\nGuard our sleep, our rest, our shining bed.\n\nLet them reveal true visions to us in our sleep,\nO high-prince of the universe, O great king of the mysteries!\n\nMay no demons, no ill, no calamity or terrifying dreams\nDisturb our rest, our willing, prompt repose.\n\nMay our watch be holy, our work, our task,\nOur sleep, our rest without let, without break.","note":"A short night prayer asking the angels to guard sleep, said at bedtime or at the close of a vigil.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-blessing-munster","title":"Patrick's Blessing on Munster","by":"Attributed to Saint Patrick","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"blessing","occasion":["blessing","home","nature"],"text":"God's blessing upon Munster,\nMen, women, children!\nA blessing on the land\nWhich gives them fruit!\n\nA blessing on every wealth\nWhich is brought forth on their marches!\nNo one to be in want of help:\nGod's blessing upon Munster!\n\nA blessing on their peaks,\nOn their bare flagstones,\nA blessing on their glens,\nA blessing on their ridges!\n\nLike sand of sea under ships\nBe the number of their hearths:\nOn slopes, on plains,\nOn mountain-sides, on peaks.","note":"A blessing on a whole land and its people, lovely for a new home, a farm, or a gathering of family.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-hermits-song","title":"The Hermit's Song","by":"Traditional, Old Irish (ascribed to Manchan of Liath)","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"poem","occasion":["peace","nature","daily"],"text":"I wish, O Son of the living God, O ancient, eternal King,\nFor a hidden little hut in the wilderness that it may be my dwelling.\n\nAn all-grey lithe little lark to be by its side,\nA clear pool to wash away sins through the grace of the Holy Spirit.\n\nQuite near, a beautiful wood around it on every side,\nTo nurse many-voiced birds, hiding it with its shelter.\n\nA southern aspect for warmth, a little brook across its floor,\nA choice land with many gracious gifts such as be good for every plant.\n\nA few men of sense, we will tell their number:\nHumble and obedient, to pray to the King:\n\nFour times three, three times four, fit for every need,\nTwice six in the church, both north and south:\n\nSix pairs besides myself,\nPraying for ever the King who makes the sun shine.\n\nA pleasant church and with the linen altar-cloth, a dwelling for God from Heaven;\nThen, shining candles above the pure white Scriptures.\n\nOne house for all to go to for the care of the body,\nWithout ribaldry, without boasting, without thought of evil.\n\nThis is the husbandry I would take, I would choose, and will not hide it:\nFragrant leek, hens, salmon, trout, bees.\n\nRaiment and food enough for me from the King of fair fame,\nAnd I to be sitting for a while praying God in every place.","note":"A monk dreams of a simple hut in the woods with birds, a clear pool, and good companions; a favorite for retreat and quiet days.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-prayer-virgin","title":"A Prayer to the Virgin","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["comfort","hope","dying"],"text":"Gentle Mary, noble maiden, give us help!\nShrine of our Lord's body, casket of the mysteries!\n\nQueen of queens, pure holy maiden,\nPray for us that our wretched transgression be forgiven for Thy sake.\n\nMerciful one, forgiving one, with the grace of the Holy Spirit,\nPray with us the true-judging King of the goodly ambrosial clan.\n\nBranch of Jesse's tree in the beauteous hazel-wood,\nPray for me until I obtain forgiveness of my foul sins.\n\nMary, splendid diadem, Thou that hast saved our race,\nGlorious noble torch, orchard of Kings!\n\nBrilliant one, transplendent one, with the deed of pure chastity,\nFair golden illumined ark, holy daughter from Heaven!\n\nMother of righteousness, Thou that excellest all else,\nPray with me Thy first-born to save me on the day of Doom.\n\nNoble rare star, tree under blossom,\nPowerful choice lamp, sun that warmeth every one.\n\nLadder of the great track by which every saint ascends,\nMayst Thou be our safeguard towards the glorious Kingdom.\n\nFair fragrant seat chosen by the King,\nThe noble guest who was in Thy womb three times three months.\n\nGlorious royal porch through which He was incarnated,\nThe splendid chosen sun, Jesus, Son of the living God.\n\nFor the sake of the fair babe that was conceived in Thy womb,\nFor the sake of the holy child that is High-King in every place,\n\nFor the sake of His cross that is higher than any cross,\nFor the sake of His burial when He was buried in a stone-tomb,\n\nFor the sake of His resurrection when He arose before every one,\nFor the sake of the holy household from every place to Doom,\n\nBe Thou our safeguard in the Kingdom of the good Lord,\nThat we may meet with dear Jesus, that is our prayer, hail!","note":"An early Irish litany of names for Mary, prayed for her help and for safe passage at the end of life.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-wandering-thoughts","title":"On the Flightiness of Thought","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"poem","occasion":["daily","peace"],"text":"Shame to my thoughts, how they stray from me!\nI fear great danger from it on the day of eternal Doom.\n\nDuring the psalms they wander on a path that is not right:\nThey fash, they fret, they misbehave before the eyes of great God.\n\nThrough eager crowds, through companies of wanton women,\nThrough woods, through cities, swifter they are than the wind.\n\nNow through paths of loveliness, anon of riotous shame!\n\nWithout a ferry or ever missing a step they go across every sea:\nSwiftly they leap in one bound from earth to heaven.\n\nThey run a race of folly anear and afar:\nAfter a course of giddiness they return to their home.\n\nThough one should try to bind them or put shackles on their feet,\nThey are neither constant nor mindful to take a spell of rest.\n\nNeither sword-edge nor crack of whip will keep them down strongly:\nAs slippery as an eel's tail they glide out of my grasp.\n\nNeither lock nor firm-vaulted dungeon nor any fetter on earth,\nStronghold nor sea nor bleak fastness restrains them from their course.\n\nO beloved truly chaste Christ to whom every eye is clear,\nMay the grace of the seven-fold Spirit come to keep them, to check them!\n\nRule this heart of mine, O dread God of the elements,\nThat Thou mayst be my love, that I may do Thy will.\n\nThat I may reach Christ with His chosen companions, that we may be together!\nThey are neither fickle nor inconstant, not as I am.","note":"A monk laughs at his own wandering mind during the psalms, a gentle companion for anyone learning to pray or sit in stillness.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-michael-hymn","title":"Maelisu's Hymn to the Archangel Michael","by":"Mael Isu Ua Brolchain (died 1086)","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"hymn","occasion":["dying","comfort"],"text":"O angel!\nBear, O Michael of great miracles,\nTo the Lord my plaint.\n\nHearest thou?\nAsk of forgiving God\nForgiveness of all my vast evil.\n\nDelay not!\nCarry my fervent prayer\nTo the King, to the great King!\n\nTo my soul\nBring help, bring comfort\nAt the hour of its leaving earth.\n\nStoutly\nTo meet my expectant soul\nCome with many thousand angels!\n\nO soldier!\nAgainst the crooked, wicked, militant world\nCome to my help in earnest!\n\nDo not\nDisdain what I say!\nAs long as I live do not desert me!\n\nThee I choose,\nThat thou mayst save my soul,\nMy mind, my sense, my body.\n\nO thou of goodly counsels,\nVictorious, triumphant one,\nAngelic slayer of Antichrist!","note":"A prayer for Michael to meet the soul with many thousand angels at the hour it leaves the earth.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-marvan","title":"From King and Hermit: Marvan's Song","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature","christian"],"denom":["irish"],"type":"poem","occasion":["nature","gratitude","peace"],"text":"I have a shieling in the wood,\nNone knows it save my God:\nAn ash-tree on the hither side, a hazel-bush beyond,\nA huge old tree encompasses it.\n\nThe size of my shieling tiny, not too tiny,\nMany are its familiar paths:\nFrom its gable a sweet strain sings\nA she-bird in her cloak of the ousel's hue.\n\nA hiding mane of green-barked yew\nSupports the sky:\nBeautiful spot! the large green of an oak\nFronting the storm.\n\nA tree of apples, great its bounty!\nLike a hostel, vast!\nA pretty bush, thick as a fist, of tiny hazel-nuts,\nA green mass of branches.\n\nA choice pure spring and princely water\nTo drink:\nThere spring watercresses, yew-berries,\nIvy-bushes thick as a man.\n\nA peaceful troop, a heavy host of denizens of the soil,\nA-trysting at my house:\nTo meet them foxes come,\nHow delightful!\n\nFairest princes come to my house,\nA ready gathering:\nPure water, perennial bushes,\nSalmon, trout.\n\nA bush of rowan, black sloes,\nDusky blackthorns,\nPlenty of food, acorns, pure berries,\nBare flags.\n\nA clutch of eggs, honey, delicious mast,\nGod has sent it:\nSweet apples, red whortleberries,\nAnd blaeberries.\n\nThe bravest band make cheer to me,\nWho have not been hired:\nIn the eyes of Christ the ever-young I am no worse off\nThan thou art.\n\nThough thou rejoicest in thy own pleasures,\nGreater than any wealth;\nI am grateful for what is given me\nFrom my good Christ.\n\nWithout an hour of fighting, without the din of strife\nIn my house,\nGrateful to the Prince who giveth every good\nTo me in my shieling.","note":"The hermit Marvan tells his brother the king why his little hut in the wood is richer than a palace; read for gratitude and simple living.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-song-sea","title":"Song of the Sea","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature","christian"],"denom":["irish"],"type":"poem","occasion":["nature","comfort"],"text":"A great tempest rages on the Plain of Ler, bold across its high borders\nWind has arisen, fierce winter has slain us; it has come across the sea,\nIt has pierced us like a spear.\n\nWhen the wind sets from the east, the spirit of the wave is roused,\nIt desires to rush past us westward to the land where sets the sun,\nTo the wild and broad green sea.\n\nWhen the wind sets from the north, it urges the dark fierce waves\nTowards the southern world, surging in strife against the wide sky,\nListening to the witching song.\n\nWhen the wind sets from the west across the salt sea of swift currents,\nIt desires to go past us eastward towards the Sun-Tree,\nInto the broad long-distant sea.\n\nWhen the wind sets from the south across the land of Saxons of mighty shields,\nThe wave strikes the Isle of Scit, it surges up to the summit of Caladnet,\nAnd pounds the grey-green mouth of the Shannon.\n\nThe ocean is in flood, the sea is full, delightful is the home of ships,\nThe wind whirls the sand around the estuary,\nSwiftly the rudder cleaves the broad sea.\n\nWith mighty force the wave has tumbled across each broad river-mouth,\nWind has come, white winter has slain us, around Cantire, around the land of Alba,\nSlieve-Dremon pours forth a full stream.\n\nSon of the God the Father, with mighty hosts, save me from the horror of fierce tempests!\nRighteous Lord of the Feast, only save me from the horrid blast,\nFrom Hell with furious tempest!","note":"A storm on the sea from every wind, ending in a prayer to be kept safe; for seafarers and for stormy seasons of life.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-summer-come","title":"Summer Has Come","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["season","nature","celebration"],"text":"Summer has come, healthy and free,\nWhence the brown wood is aslope;\nThe slender nimble deer leap,\nAnd the path of seals is smooth.\n\nThe cuckoo sings sweet music,\nWhence there is smooth restful sleep;\nGentle birds leap upon the hill,\nAnd swift grey stags.\n\nHeat has laid hold of the rest of the deer:\nThe lovely cry of curly packs!\nThe white extent of the strand smiles,\nThere the swift sea is.\n\nA sound of playful breezes in the tops\nOf a black oakwood is Drum Daill,\nThe noble hornless herd runs,\nTo whom Cuan-wood is a shelter.\n\nGreen bursts out on every herb,\nThe top of the green oakwood is bushy,\nSummer has come, winter has gone,\nTwisted hollies wound the hound.\n\nThe blackbird sings a loud strain,\nTo him the live wood is a heritage,\nThe sad angry sea is fallen asleep,\nThe speckled salmon leaps.\n\nThe sun smiles over every land,\nA parting for me from the brood of cares:\nHounds bark, stags tryst,\nRavens flourish, summer has come!","note":"An Old Irish welcome to summer, good for May Day or a summer gathering.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-song-summer","title":"Song of Summer","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["season","nature"],"text":"Summer-time, season supreme!\nSplendid is colour then.\nBlackbirds sing a full lay\nIf there be a slender shaft of day.\n\nThe dust-coloured cuckoo calls aloud:\nWelcome, splendid summer!\nThe bitterness of bad weather is past,\nThe boughs of the wood are a thicket.\n\nPanic startles the heart of the deer,\nThe smooth sea runs apace:\nSeason when ocean sinks asleep,\nBlossom covers the world.\n\nBees with puny strength carry\nA goodly burden, the harvest of blossoms;\nUp the mountain-side kine take with them mud,\nThe ant makes a rich meal.\n\nThe harp of the forest sounds music,\nThe sail gathers, perfect peace;\nColour has settled on every height,\nHaze on the lake of full waters.\n\nThe corncrake, a strenuous bard, discourses,\nThe lofty cold waterfall sings\nA welcome to the warm pool:\nThe talk of the rushes has come.\n\nLight swallows dart aloft,\nLoud melody encircles the hill,\nThe soft rich mast buds,\nThe stuttering quagmire prattles.\n\nThe peat-bog is as the raven's coat,\nThe loud cuckoo bids welcome,\nThe speckled fish leaps:\nStrong is the bound of the swift warrior.\n\nMan flourishes, the maiden buds\nIn her fair strong pride.\nPerfect each forest from top to ground,\nPerfect each great stately plain.\n\nDelightful is the season's splendour,\nRough winter has gone:\nEvery fruitful wood shines white,\nA joyous peace is summer.\n\nA flock of birds settles\nIn the midst of meadows,\nThe green field rustles,\nWherein is a brawling white stream.\n\nA wild longing is on you to race horses,\nThe ranked host is ranged around:\nA bright shaft has been shot into the land,\nSo that the water-flag is gold beneath it.\n\nA timorous, tiny, persistent little fellow\nSings at the top of his voice,\nThe lark sings clear tidings:\nSurpassing summer-time of delicate hues!","note":"A joyful catalogue of summer, from the cuckoo to the bees; read at midsummer or a garden blessing.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-summer-gone","title":"Summer Is Gone","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["season","nature"],"text":"My tidings for you: the stag bells,\nWinter snows, summer is gone.\n\nWind high and cold, low the sun,\nShort his course, sea running high.\n\nDeep-red the bracken, its shape all gone:\nThe wild-goose has raised his wonted cry.\n\nCold has caught the wings of birds;\nSeason of ice, these are my tidings.","note":"Eight short lines for the turn to autumn and winter.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-song-winter","title":"A Song of Winter","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["season","nature"],"text":"Cold, cold!\nCold to-night is broad Moylurg,\nHigher the snow than the mountain-range,\nThe deer cannot get at their food.\n\nCold till Doom!\nThe storm has spread over all:\nA river is each furrow upon the slope,\nEach ford a full pool.\n\nA great tidal sea is each loch,\nA full loch is each pool:\nHorses cannot get over the ford of Ross,\nNo more can two feet get there.\n\nThe fish of Ireland are a-roaming,\nThere is no strand which the wave does not pound,\nNot a town there is in the land,\nNot a bell is heard, no crane talks.\n\nThe wolves of Cuan-wood get\nNeither rest nor sleep in their lair,\nThe little wren cannot find\nShelter in her nest on the slope of Lon.\n\nKeen wind and cold ice\nHas burst upon the little company of birds,\nThe blackbird cannot get a lee to her liking,\nShelter for its side in Cuan-wood.\n\nCosy our pot on its hook,\nCrazy the hut on the slope of Lon:\nThe snow has crushed the wood here,\nToilsome to climb up Ben-bo.\n\nGlenn Rye's ancient bird\nFrom the bitter wind gets grief;\nGreat her misery and her pain,\nThe ice will get into her mouth.\n\nFrom flock and from down to rise:\nTake it to heart! were folly for thee:\nIce in heaps on every ford:\nThat is why I say 'cold'!","note":"A hermit on a cold hillside describes deep winter; for the dark of the year.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-arran","title":"Arran","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature"],"denom":["irish","scottish"],"type":"poem","occasion":["nature","home"],"text":"Arran of the many stags,\nThe sea strikes against its shoulder,\nIsle in which companies are fed,\nRidge on which blue spears are reddened.\n\nSkittish deer are on her peaks,\nDelicious berries on her manes,\nCool water in her rivers,\nMast upon her dun oaks.\n\nGreyhounds are in it and beagles,\nBlackberries and sloes of the dark blackthorn,\nHer dwellings close against the woods,\nDeer scattered about her oak-woods.\n\nGleaning of purple upon her rocks,\nFaultless grass upon her slopes,\nOver her fair shapely crags\nNoise of dappled fawns a-skipping.\n\nSmooth is her level land, fat are her swine,\nBright are her fields,\nHer nuts upon the tops of her hazel-wood,\nLong galleys sailing past her.\n\nDelightful it is when the fair season comes,\nTrout under the brinks of her rivers,\nSeagulls answer each other round her white cliff,\nDelightful at all times is Arran!","note":"A song of praise for the Isle of Arran, for those who love a place and its creatures.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-pangur-meyer","title":"The Monk and His Pet Cat","by":"Traditional, Old Irish (ninth century)","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["daily","gratitude","home"],"text":"I and my white Pangur\nHave each his special art:\nHis mind is set on hunting mice,\nMine is upon my special craft.\n\nI love to rest, better than any fame!\nWith close study at my little book:\nWhite Pangur does not envy me:\nHe loves his childish play.\n\nWhen in our house we two are all alone:\nA tale without tedium!\nWe have, sport never-ending!\nSomething to exercise our wit.\n\nAt times by feats of derring-do\nA mouse sticks in his net,\nWhile into my net there drops\nA difficult problem of hard meaning.\n\nHe points his full shining eye\nAgainst the fence of the wall:\nI point my clear though feeble eye\nAgainst the keenness of science.\n\nHe rejoices with quick leaps\nWhen in his sharp claw sticks a mouse:\nI too rejoice when I have grasped\nA problem difficult and dearly loved.\n\nThough we are thus at all times,\nNeither hinders the other,\nEach of us pleased with his own art\nAmuses himself alone.\n\nHe is a master of the work\nWhich every day he does:\nWhile I am at my own work\nTo bring difficulty to clearness.","note":"The famous poem of a scholar and his white cat Pangur, each happy at his own work.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-colum-greeting","title":"From Colum Cille's Greeting to Ireland","by":"Attributed to Saint Columba (Colum Cille)","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish","scottish"],"type":"poem","occasion":["home","grief","blessing"],"text":"Delightful to be on the Hill of Howth\nBefore going over the white-haired sea:\nThe dashing of the wave against its face,\nThe bareness of its shores and of its border.\n\nI stretch my glance across the brine\nFrom the firm oaken planks:\nMany are the tears of my bright soft grey eye\nAs I look back upon Erin.\n\nMy mind is upon Erin,\nUpon Loch Lene, upon Linny,\nUpon the land where Ulstermen are,\nUpon gentle Munster and upon Meath.\n\nMelodious her clerics, melodious her birds,\nGentle her youths, wise her elders,\nIllustrious her men, famous to behold,\nIllustrious her women for fond espousal.\n\nCarry with thee, thou fair youth,\nMy blessing and my benediction,\nOne half upon Erin, sevenfold,\nAnd half upon Alba at the same time.\n\nCarry my blessing with thee to the West,\nMy heart is broken in my breast:\nShould sudden death overtake me,\nIt is for my great love of the Gael.\n\nWere all Alba mine\nFrom its centre to its border,\nI would rather have the site of a house\nIn the middle of fair Derry.\n\nIt is for this I love Derry,\nFor its smoothness, for its purity;\nAll full of angels\nIs every leaf on the oaks of Derry.\n\nDelightful it is,\nThe deep-red ocean where the sea-gulls cry,\nAs I come from Derry afar,\nIt is peaceful and it is delightful.","note":"Columba in exile on Iona sends his blessing home to Ireland and to his beloved oak grove at Derry; for anyone far from home.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-angus-culdee","title":"On Angus the Culdee","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"poem","occasion":["funeral","grief","nature"],"text":"Delightful to sit here thus\nBy the side of the cold pure Nore:\nThough it was frequented, it was never a path of raids\nIn glorious Disert Bethech.\n\nDisert Bethech, where dwelt the man\nWhom hosts of angels were wont to visit;\nA pious cloister behind a circle of crosses,\nWhere Angus son of Oivlen used to be.\n\nAngus from the assembly of Heaven,\nHere are his tomb and his grave:\n'Tis hence he went to death,\nOn a Friday, to holy Heaven.\n\n'Tis in Clonenagh he was reared,\nIn Clonenagh he was buried:\nIn Clonenagh of many crosses\nHe first read his psalms.","note":"A visitor sits by the river at the grave of a beloved holy man; read at a graveside or a memorial by water.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-colum-scribe","title":"Colum Cille the Scribe","by":"Attributed to Saint Columba (Colum Cille)","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish","scottish"],"type":"poem","occasion":["daily","gratitude"],"text":"My hand is weary with writing,\nMy sharp quill is not steady,\nMy slender-beaked pen juts forth\nA black draught of shining dark-blue ink.\n\nA stream of the wisdom of blessed God\nSprings from my fair-brown shapely hand:\nOn the page it squirts its draught\nOf ink of the green-skinned holly.\n\nMy little dripping pen travels\nAcross the plain of shining books,\nWithout ceasing for the wealth of the great:\nWhence my hand is weary with writing.","note":"Columba with a tired hand still copying the sacred books; for writers, teachers, and any faithful work.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-scribe","title":"The Scribe","by":"Traditional, Old Irish (ninth century)","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature","christian"],"denom":["irish"],"type":"poem","occasion":["nature","daily","peace"],"text":"A hedge of trees surrounds me,\nA blackbird's lay sings to me;\nAbove my lined booklet\nThe trilling birds chant to me.\n\nIn a grey mantle from the top of bushes\nThe cuckoo sings:\nVerily, may the Lord shield me!\nWell do I write under the greenwood.","note":"Written in the margin of a manuscript: a monk writing under the trees with a blackbird singing.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-crucifixion","title":"The Crucifixion","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"poem","occasion":["grief","comfort"],"text":"At the cry of the first bird\nThey began to crucify Thee, O cheek like a swan!\nIt were not right ever to cease lamenting:\nIt was like the parting of day from night.\n\nAh! though sore the suffering\nPut upon the body of Mary's Son:\nSorer to Him was the grief\nThat was upon her for His sake.","note":"Two quatrains on Good Friday and on Mary's grief, for a mother or father in mourning.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-pilgrim-rome","title":"The Pilgrim at Rome","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"poem","occasion":["daily","peace"],"text":"To go to Rome\nIs much of trouble, little of profit:\nThe King whom thou seekest here,\nUnless thou bring Him with thee, thou wilt not find.","note":"Four lines on carrying God within you wherever you go.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-hospitality","title":"Hospitality","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"blessing","occasion":["home","blessing"],"text":"O King of stars!\nWhether my house be dark or bright,\nNever shall it be closed against any one,\nLest Christ close His house against me.\n\nIf there be a guest in your house\nAnd you conceal aught from him,\n'Tis not the guest that will be without it,\nBut Jesus, Mary's Son.","note":"The open door of the Irish house, kept open for Christ in every guest; for a home blessing or a welcome.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-blackbird-meyer","title":"The Blackbird","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["nature","peace"],"text":"Ah, blackbird, thou art satisfied\nWhere thy nest is in the bush:\nHermit that clinkest no bell,\nSweet, soft, peaceful is thy note.","note":"Four lines to a blackbird singing like a hermit without a bell.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-triads","title":"From the Triads of Ireland","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","all"],"denom":["irish"],"type":"reflection","occasion":["daily","gratitude"],"text":"Three slender things that best support the world: the slender stream of milk from the cow's dug into the pail; the slender blade of green corn upon the ground; the slender thread over the hand of a skilled woman.\n\nThree fair things that hide ugliness: good manners in the ill-favoured; skill in a serf; wisdom in the misshapen.\n\nThree sparks that kindle love: a face, demeanour, speech.\n\nThree things that constitute a physician: a complete cure; leaving no blemish behind; a painless examination.","note":"Old Irish wisdom sayings in threes, a style the Celtic peoples loved.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-deirdre-farewell","title":"Deirdre's Farewell to Scotland","by":"Traditional, Old Irish","tr":"Kuno Meyer","year":1911,"trad":["celtic","nature"],"denom":["irish","scottish"],"type":"poem","occasion":["home","grief","nature"],"text":"A beloved land is yon land in the east,\nAlba with its marvels.\nI would not have come hither out of it,\nHad I not come with Noisi.\n\nBeloved are Dun Fidga and Dun Finn,\nBeloved is the fortress above them,\nBeloved is the Isle of the Thorn-bush,\nAnd beloved is Dun Sweeny.\n\nCaill Cuan!\nUnto which Ainnle would go, alas!\nShort we thought the time there,\nNoisi and I in the land of Alba.\n\nGlen Lay!\nThere I used to sleep under a shapely rock.\nFish and venison and badger's fat,\nThat was my portion in Glen Lay.\n\nGlen Massan!\nTall is its wild garlic, white are its stalks:\nWe used to have a broken sleep\nOn the grassy river-mouth of Massan.\n\nGlen Etive!\nThere I raised my first house.\nDelightful its house! when we rose in the morning\nA sunny cattle-fold was Glen Etive.\n\nGlen Urchain!\nThat was the straight, fair-ridged glen!\nNever was man of his age prouder\nThan Noisi in Glen Urchain.\n\nGlen Da Ruadh!\nHail to him who hath it as an heritage!\nSweet is the cuckoo's voice on bending branch\nOn the peak above Glen Da Ruadh.\n\nBeloved is Draighen over a firm beach!\nBeloved its water in pure sand!\nI would never have left it, from the east,\nHad I not come with my beloved.","note":"Deirdre names the glens of Scotland where she lived happily with her beloved; for leaving a home or remembering a love.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-old-woman-beare","title":"From the Lament of the Old Woman of Beare","by":"Traditional, Old Irish (ninth century)","tr":"Kuno Meyer","year":1911,"trad":["celtic","christian"],"denom":["irish"],"type":"poem","occasion":["grief","comfort","dying"],"text":"The wave of the great sea talks aloud,\nWinter has arisen:\nFermuid the son of Mugh to-day\nI do not expect on a visit.\n\nI know what they are doing:\nThey row and row across\nThe reeds of the Ford of Alma:\nCold is the dwelling where they sleep.\n\n'Tis 'O my God!'\nTo me to-day, whatever will come of it.\nI must take my garment even in the sun:\nThe time is at hand that shall renew me.\n\nYouth's summer in which we were\nI have spent with its autumn:\nWinter-age which overwhelms all men,\nTo me has come its beginning.\n\nThe flood-wave\nAnd the second ebb-tide:\nThey have all reached me,\nSo that I know them well.\n\nThe flood-wave\nWill not reach the silence of my kitchen:\nThough many are my company in darkness,\nA hand has been laid upon them all.\n\nO happy the isle of the great sea\nWhich the flood reaches after the ebb!\nAs for me, I do not expect\nFlood after ebb to come to me.\n\nThere is scarce a little place to-day\nThat I can recognise:\nWhat was on flood\nIs all on ebb.","note":"An old woman remembers her youth as the tide goes out; one of the great Irish poems of aging.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-isles-happy","title":"From the Isles of the Happy","by":"Traditional, Old Irish (from The Voyage of Bran)","tr":"Kuno Meyer","year":1911,"trad":["celtic","pagan"],"denom":["irish"],"type":"poem","occasion":["comfort","hope","grief"],"text":"I bring a branch of Evin's apple-tree,\nIn shape alike to those you know:\nTwigs of white silver are upon it,\nBuds of crystal with blossoms.\n\nAn ancient tree there is in bloom,\nOn which birds call to the Hours:\nIn harmony of song they all are wont\nTo chant together every Hour.\n\nUnknown is wailing or treachery\nIn the homely cultivated land:\nThere is nothing rough or harsh,\nBut sweet music striking on the ear.\n\nWithout grief, without gloom, without death,\nWithout any sickness or debility:\nThat is the sign of Evin:\nUncommon is the like of such a marvel.","note":"A woman from the Otherworld sings of an island without grief or death; an old Irish picture of the land beyond.","voice":"brian","source":{"name":"Selections from Ancient Irish Poetry, Kuno Meyer (1911)","url":"https://www.gutenberg.org/ebooks/32030"},"rights":"pd","pd":"published 1911; Kuno Meyer died 1919"},{"id":"celt-columba-iona","title":"Saint Columba in Iona","by":"Attributed to Saint Columba","tr":"Eugene O'Curry","year":1913,"trad":["celtic","christian"],"denom":["irish","scottish"],"type":"poem","occasion":["nature","peace","daily"],"text":"Delightful would it be to me\nOn a pinnacle of rock,\nThat I might often see\nThe face of the ocean;\nThat I might watch its heaving waves\nOver the wide sea\nWhen they chant music to their Father\nUpon the world's course;\nThat I might see its level sparkling strand,\nIt would be no cause of sorrow;\nThat I might hear the song of the wonderful birds,\nSource of happiness;\nThat I might hear the thunder of the clamorous waves\nUpon the rocks;\nThat I might hear the roar by the side of the church\nOf the surrounding sea;\nThat I might watch its noble bird-flocks\nFlying over the watery surf;\nThat I might see the ocean-monsters,\nGreatest of all wonders;\nThat I might observe its ebb and flood\nIn their cycles;\nThat my mystical name might be, i'faith,\n\"Cul ri Erin.\"\nThat on my heart contrition might fall\nOn looking upon her;\nThat I might bewail my evils all,\nThough it were not easy to number them;\nThat I might bless the Lord\nWho orders all;\nHeaven with its countless bright orders\nLand, strand and flood;\nThat I might search in all the books\nThat which would help my soul;\nAt times kneeling to the Heaven of my heart,\nAt times singing psalms;\nAt times meditating on the King of Heaven,\nChief of the Holy Ones;\nAt times at work without compulsion\nThis would be delightful.\nAt times plucking duilisc from the rocks;\nAt other times fishing;\nAt times distributing food to the poor,\nAt times in a hermitage;\nThe best guidance from the presence of God\nHas been vouchsafed to me;\nThe King whom I serve will keep from me\nAll things that would deceive me.","note":"Columba longs for a rock above the sea where he can pray, work, and watch the waves; a favorite of Iona pilgrims.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-manchan","title":"The Song of Manchan the Hermit","by":"Attributed to Manchan of Liath (died 665)","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"poem","occasion":["peace","nature","daily"],"text":"I wish, O Son of the Living God, O Ancient Eternal King,\nFor a hidden hut in the wilderness, a simple secluded thing.\n\nThe all-blithe lithe little lark in his place, chanting his lightsome lay;\nThe calm, clear pool of the Spirit's grace, washing my sins away.\n\nA wide, wild woodland on every side, its shades the nursery\nOf glad-voiced songsters, who at day-dawn chant their sweet psalm for me.\n\nA southern aspect to catch the sun, a brook across the floor,\nA choice land, rich with gracious gifts, down-stretching from my door.\n\nFew men and wise, these I would prize, men of content and power,\nTo raise Thy praise throughout the days at each canonical hour.\n\nFour times three, three times four, fitted for every need,\nTo the King of the Sun praying each one, this were a grace, indeed.\n\nTwelve in the church to chant the hours, kneeling there twain and twain;\nAnd I before, near the chancel door, listening their low refrain.\n\nA pleasant church with an Altar-cloth, where Christ sits at the board,\nAnd a shining candle shedding its ray on the white words of the Lord.\n\nBrief meals between, when prayer is done, our modest needs supply;\nNo greed in our share of the simple fare, no boasting or ribaldry.\n\nThis is the husbandry I choose, laborious, simple, free,\nThe fragrant leek about my door, the hen and the humble bee.\n\nRough raiment of tweed, enough for my need, this will my King allow;\nAnd I to be sitting praying to God under every leafy bough.","note":"Hull's verse rendering of the hermit's wish for a hidden hut, a clear pool, and a praying company.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-be-thou-my-vision","title":"A Prayer (Be Thou My Vision)","by":"Traditional, Old Irish (eighth century)","tr":"Eleanor Hull, from the prose of Mary Byrne","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["daily","morning","funeral","hope"],"text":"Be Thou my Vision, O Lord of my heart,\nNaught is all else to me, save that Thou art.\n\nThou my best thought by day and by night,\nWaking or sleeping, Thy presence my light.\n\nBe Thou my Wisdom, Thou my true Word;\nI ever with Thee, Thou with me, Lord.\n\nThou my great Father, I thy dear son;\nThou in me dwelling, I with Thee one.\n\nBe Thou my battle-shield, sword for the fight,\nBe Thou my dignity, Thou my delight.\n\nThou my soul's shelter, Thou my high tower;\nRaise Thou me heavenward, Power of my power.\n\nRiches I heed not or man's empty praise,\nThou mine inheritance now and always.\n\nThou, and Thou only, first in my heart,\nHigh King of Heaven, my treasure Thou art.\n\nKing of the seven heavens, grant me for dole,\nThy love in my heart, Thy light in my soul.\n\nThy light from my soul, Thy love from my heart,\nKing of the seven heavens, may they never depart.\n\nWith the High King of heaven, after victory won,\nMay I reach heaven's joys, O Bright heaven's Sun!\n\nHeart of my own heart, whatever befall,\nStill be my Vision, O Ruler of all.","note":"Hull's verse of the old Irish prayer, the text the well-known hymn grew from; spoken at funerals, weddings, and morning prayer.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-pangur-flower","title":"Pangur Ban (The Student and His Cat)","by":"Traditional, Old Irish (ninth century)","tr":"Robin Flower","year":1913,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["daily","gratitude","home"],"text":"I and Pangur Ban, my cat,\n'Tis a like task we are at;\nHunting mice is his delight,\nHunting words I sit all night.\n\nBetter far than praise of men\n'Tis to sit with book and pen;\nPangur bears me no ill-will,\nHe, too, plies his simple skill.\n\n'Tis a merry thing to see\nAt our tasks how glad are we,\nWhen at home we sit and find\nEntertainment to our mind.\n\nOftentimes a mouse will stray\nIn the hero Pangur's way;\nOftentimes my keen thought set\nTakes a meaning in its net.\n\n'Gainst the wall he sets his eye\nFull and fierce and sharp and sly;\n'Gainst the wall of knowledge I\nAll my little wisdom try.\n\nWhen a mouse darts from its den,\nO! how glad is Pangur then;\nO! what gladness do I prove\nWhen I solve the doubts I love.\n\nSo in peace our task we ply,\nPangur Ban, my cat, and I;\nIn our arts we find our bliss,\nI have mine, and he has his.\n\nPractice every day has made\nPangur perfect in his trade;\nI get wisdom day and night,\nTurning darkness into light.","note":"Robin Flower's rhyming version of the scholar and his white cat, written in the margin of a monastery book.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-seven-archangels","title":"The Song of the Seven Archangels","by":"Traditional, Irish","tr":"Ernest Rhys","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["daily","comfort"],"text":"Now, Gabriel, be with my heart\nOn this first day of seven,\nHe, first of the Archangels;\nAnd Thou, High King of Heaven.\n\nMichael be mine, if Monday dawn,\nMichael I call upon,\nThere is none like thee, Michael,\nNone but Jesu, Mary's Son.\n\nAnd oh if Tuesday sorrow bring,\nLet Raphael help it forth,\nOne of the seven that hears us weep,\nSad women of this earth.\n\nAnd Uriel hear, if Wednesday wake,\nIn his nobility,\nAnd heal our wounds and care for us\nAnd calm this wind-torn sea.\n\nAnd Sariel, should Thursday come\nWith wilder wind and seas,\nOn Sariel I cry aloud\nFor that solace which is his.\n\nFor sorrow's fast on Friday,\nOut of my need I cry\nOn Rumiel, my heart's near friend,\nThough Heaven I know is nigh.\n\nAnd Saturday, on Panchel,\nWhile this yellow world is mine,\nI call on him while shake the leaves\nAnd the yellow sun doth shine.\n\nThe Trinity protect me still:\nOh blessed Trinity,\nAnd be my stay in danger's hour;\nProtect and prosper me.","note":"An archangel for each day of the week, ending in the Trinity; a prayer for the days of a long week.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-saints-four-seasons","title":"Saints of Four Seasons (The Feilire of Adamnan)","by":"Ascribed to Saint Adamnan of Iona","tr":"P. J. McCall","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish","scottish"],"type":"litany","occasion":["season","dying","comfort"],"text":"Saints of Four Seasons!\nSaints of the Year!\nLoving, I pray to you; longing, I say to you:\nSave me from angers, dreeings, and dangers!\nSaints of Four Seasons!\nSaints of the Year!\n\nSaints of Green Springtime!\nSaints of the Year!\nPatraic and Grighair, Brighid be near!\nMy last breath gather with God's Foster Father!\nSaints of Green Springtime!\nSaints of the Year!\n\nSaints of Gold Summer!\nSaints of the Year!\n(Poesy wingeth me! Fancy far bringeth me!)\nGuide ye me on to Mary's Sweet Son!\nSaints of Gold Summer!\nSaints of the Year!\n\nSaints of Red Autumn!\nSaints of the Year!\nLo! I am cheery! Michil and Mary\nOpen wide Heaven to my soul bereaven!\nSaints of Red Autumn!\nSaints of the Year!\n\nSaints of Grey Winter\nSaints of the Year!\nOutside God's Palace fiends wait in malice:\nLet them not win my soul going in!\nSaints of Grey Winter!\nSaints of the Year!\n\nSaints of Four Seasons!\nSaints of the Year!\nWaking or sleeping, to my grave creeping,\nLife in its Night, hold me God's light!\nSaints of Four Seasons!\nSaints of the Year!","note":"An old Irish litany calling on the saints of every season to gather the last breath and guide the soul home.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-feathered-hermit","title":"The Feathered Hermit","by":"Traditional, Old Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["nature","peace"],"text":"Blackbird, who pourest praise,\nDeep hidden 'neath the bough,\nNo bell to call the Hours\nThou needest, thou;\nEach hour, O hermit, from thy throat,\nWells thy sweet, soft, peaceful note.","note":"The blackbird as a hermit who needs no bell to keep the hours of prayer.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-aphorism","title":"An Aphorism","by":"Traditional, Old Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","all"],"denom":["irish"],"type":"poem","occasion":["dying","daily"],"text":"Time was, I was not here;\nShort the time for me, I fear!\nDeath comes, that is clear;\nIt is not clear when death is near.","note":"Four lines on the shortness of life, for a quiet moment of reflection.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-blackbird-wall-green","title":"The Blackbird (Within My Wall of Green)","by":"Traditional, Old Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["nature","peace"],"text":"High trees close me round\nFar from the ground the blackbird sings,\nTrilling, it chants its lay\nAbove my well-lined book to-day.\n\nIn its soft veil of grey\nThe wayward cuckoo calls aloud;\nWithin my wall of green,\nMy God shrouds me, all unseen.","note":"Hull's version of the scribe's poem, the blackbird above the book and God's shelter all around.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-deus-meus","title":"Deus Meus","by":"Mael Isu of Derry (died 1038)","tr":"George Sigerson","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"hymn","occasion":["daily","hope"],"text":"Deus meus adiuva me,\nGive me thy love, O Christ, I pray,\nGive me thy love, O Christ, I pray,\nDeus meus adiuva me.\n\nIn meum cor ut sanum sit,\nPour, loving King, Thy love in it,\nPour, loving King, Thy love in it,\nIn meum cor ut sanum sit.\n\nDomine, da ut peto a te,\nO, pure bright sun, give, give to-day,\nO, pure bright sun, give, give to-day,\nDomine, da ut peto a te.\n\nHanc spero rem et quaero quam\nThy love to have where'er I am,\nThy love to have where'er I am,\nHanc spero rem et quaero quam.\n\nTuum amorem sicut uis,\nGive to me swiftly, strongly, this,\nGive to me swiftly, strongly, this,\nTuum amorem sicut uis.\n\nQuaero, postulo, peto a te,\nThat I in heaven, dear Christ, may stay,\nThat I in heaven, dear Christ, may stay,\nQuaero, postulo, peto a te.\n\nDomine, Domine, exaudi me,\nFill my soul, Lord, with Thy love's ray,\nFill my soul, Lord, with Thy love's ray,\nDomine, Domine, exaudi me.\nDeus meus adiuva me,\nDeus meus adiuva me.","note":"A Latin and Irish love prayer to Christ, with each Latin line answered in English.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-souls-desire","title":"The Soul's Desire","by":"Traditional, Old Irish (author and date unknown)","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["hope","dying","daily"],"text":"It were my soul's desire\nTo see the face of God;\nIt were my soul's desire\nTo rest in His abode.\n\nIt were my soul's desire\nTo study zealously;\nThis, too, my soul's desire,\nA clear rule set for me.\n\nIt were my soul's desire\nA spirit free from gloom;\nIt were my soul's desire\nNew life beyond the Doom.\n\nIt were my soul's desire\nTo shun the chills of hell;\nYet more my soul's desire\nWithin His house to dwell.\n\nIt were my soul's desire\nTo imitate my King,\nIt were my soul's desire\nHis ceaseless praise to sing.\n\nIt were my soul's desire\nWhen heaven's gate is won\nTo find my soul's desire\nClear shining like the sun.\n\nGrant, Lord, my soul's desire,\nDeep waves of cleansing sighs;\nGrant, Lord, my soul's desire\nFrom earthly cares to rise.\n\nThis still my soul's desire\nWhatever life afford,\nTo gain my soul's desire\nAnd see Thy face, O Lord.","note":"A longing to see the face of God and dwell in God's house, spoken at the end of life or in morning prayer.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-gormliath","title":"Gormliath's Lament for Nial Black-Knee","by":"Attributed to Queen Gormliath (died 946)","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"poem","occasion":["grief","funeral"],"text":"Move, O Monk, thy foot away!\nLift it from the grave of Nial!\nAll too high thou heap'st the pile;\nAll too deep thou diggest the clay.\n\nBrown-haired Monk, most gentle friend,\nPress not with thy foot the soil\nNial to cover, heavy toil,\nOf thy labours make an end.\n\nMournful priest, thy prayers delay,\nClose not yet the prince's tomb,\nMake an opening, for I come;\nMove, O Monk, thy foot away!\n\nNot my will that brought thee bound,\nBlack-kneed Nial, with heart of gold!\nWhen mine arms his form enfold,\nRaise his stone, and smooth his mound.\n\nGormliath I, a Queen commands,\nDaughter of King Flann the brave;\nPress not then upon his grave;\nMove, O Monk, thy foot away!","note":"A queen at her husband's grave asks the monk to wait before he closes it; for the raw first grief at a burial.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-consecration","title":"Consecration","by":"Muireadhach Albanach O Dalaigh (thirteenth century)","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish","scottish"],"type":"prayer","occasion":["daily","peace","forgiveness"],"text":"How great the tale, that there should be,\nIn God's Son's heart, a place for me!\nThat on a sinner's lips like mine,\nThe cross of Jesus Christ should shine!\n\nChrist Jesus, bend me to Thy will,\nMy feet to urge, my griefs to still;\nThat even my flesh and blood may be\nA temple sanctified to Thee.\n\nNo rest, no calm, my soul may win,\nBecause my body craves to sin,\nTill Thou, dear Lord, Thyself impart\nPeace to my head, light to my heart.\n\nMay consecration come from far,\nSoft shining like the evening star!\nMy toilsome path make plain to me,\nUntil I come to rest in Thee.","note":"A poet asks Christ to make his whole life a temple, ending in rest; for a dedication or a new beginning.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-teach-me-trinity","title":"From Teach Me, O Trinity","by":"Muireadhach Albanach O Dalaigh (thirteenth century)","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish","scottish"],"type":"prayer","occasion":["forgiveness","healing"],"text":"Teach me, O Trinity,\nAll men sing praise to Thee,\nLet me not backward be,\nTeach me, O Trinity.\n\nCome Thou and dwell with me,\nLord of the holy race;\nMake here thy resting-place,\nHear me, O Trinity.\n\nThat I Thy love may prove,\nTeach Thou my heart and hand,\nEver at Thy command\nSwiftly to move.\n\nLike to a rotting tree\nIs this vile heart of me;\nLet me Thy healing see,\nHelp me, O Trinity.\n\nIn my adversity\nNo great man stooped to me,\nNo good man pitied me,\nGod ope'd His heart to me.\n\nTruth art Thou, truth I crave,\nIf on a lie I rest, I'm lost;\nMy vow demands my uttermost;\nSave, Trinity, O save!","note":"A plain and honest prayer to the Trinity for teaching, healing, and truth.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-hymn-virgin","title":"Hymn to the Virgin Mary","by":"Conor O'Riordan (about 1750)","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"hymn","occasion":["comfort","dying","healing"],"text":"Queen of all Queens, oh! Wonder of the loveliness of women,\nHeart which hath held in check for us the righteous wrath of God;\nStrong Staff of Light, and Fosterer of the Bright Child of heaven,\nPray thou for us as we now pray that we may be forgiven.\n\nShe of the King of Stars beloved, stainless, undefiled,\nChrist chose as His Mother-nurse, to Him, the stainless Child;\nWithin her breast, as in a nest, the Paraclete reposes,\nLily among fairest flowers, Rose amid red roses.\n\nShe, the bright unsheathed sword to guard our souls in anguish,\nShe, the flawless limber-branch, to cover those that languish;\nWhere her healing mantle flows, may I find my hiding,\n'Neath the fringes of her robe constantly abiding.\n\nHostile camps upon the plain, sharp swords clashed together,\nStricken fleets across the main stressed by wintry weather;\nWeary sickness on my heart, sinful thoughts alluring,\nAll the fever of my soul clings to her for curing.\n\nShe the Maid the careful king of the wide wet world chooses,\nIn her speech forgiveness lies, no suppliant she refuses;\nWhite Star of our troubled sea, on thy name I'm crying,\nThat Christ may draw in His spread net the living and the dying.","note":"An eighteenth century Irish hymn to Mary, Star of the Sea, prayed for the living and the dying.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-christmas-hymn","title":"Christmas Hymn","by":"Traditional, Irish","tr":"Douglas Hyde","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"hymn","occasion":["celebration","birth","season"],"text":"Hail to thee, thou holy Babe,\nIn the manger now so poor,\nYet so rich Thou art, I ween,\nHigh within the highest door.\n\nLittle Babe who art so great,\nChild so young who art so old,\nIn the manger small His room\nWhom not heaven itself could hold.\n\nMotherless, with mother here,\nFatherless, a tiny span,\nEver God in heaven's height,\nFirst to-night becoming man.\n\nFather, not more old than thou?\nMother, younger, can it be!\nOlder, younger is the Son,\nYounger, older, she than He.","note":"A Connacht Christmas hymn full of wonder at the great God become a little child.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-mary-of-graces","title":"O Mary of Graces","by":"Traditional, Irish","tr":"Douglas Hyde","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["blessing","daily","comfort"],"text":"O Mary of Graces\nAnd Mother of God,\nMay I tread in the paths\nThat the righteous have trod.\n\nAnd mayest thou save me\nFrom evil's control,\nAnd mayest thou save me\nIn body and soul.\n\nAnd mayest thou save me\nBy land and by sea,\nAnd mayest thou save me\nFrom tortures to be.\n\nMay the guard of the angels\nAbove me abide,\nMay God be before me\nAnd God at my side.","note":"A short folk prayer for protection by land and sea, with God before and beside.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-cattle-shed","title":"The Cattle-Shed","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"poem","occasion":["season","celebration","birth"],"text":"O Trinity of the glorious saints, I marvel\nthat the White Prince of the Kingdom did descend\nas a child into the pure womb of Mary.\nNine months the Master of the Angels stayed\nin humility and in great lowliness with her,\nlighting a furnace of love within her.\nHe came down to earth,\nthe White Lamb, our loosener from sin.\nO Mother, who found not a dwelling in the city,\ntill thou didst come to the stable to seek a bed;\nthere wast thou lying in poverty,\nwithout wine, without flesh, or one taste in thy mouth;\non the mean barley chaff in the cattle-shed,\nshe brought forth the only Son of God of the Apostles.\nCold and misery you complained not of as your portion,\nand was it not the holy sight in the manger of the ass?","note":"An Irish folk meditation on the poverty of the stable at Christmas.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-hail-mary-child","title":"Hail to Thee, O Mary","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["birth","comfort"],"text":"Hail to thee, O Mary,\nFull of holy graces,\nThou our loving Mother\nWhom the child embraces.\nHail to thee, O Mary,\nWhere are our alarms?\nIs the little Child not blessed,\nLying in thine arms?","note":"A gentle verse to Mary with the child in her arms, good for a new mother.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-two-prayers","title":"Two Prayers","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["daily","peace"],"text":"A low prayer, a high prayer, I send through space.\nArrange them Thyself, O Thou King of Grace.","note":"Two lines that hand every prayer, low or high, to God to arrange.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-o-mary-blessed","title":"O Mary, O Blessed Mother","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"hymn","occasion":["hope","season"],"text":"O Mary, O blessed Mother,\npraise from my heart I sing,\nit is thou didst bear our Saviour,\nour Lord and our King.\nIn the stable of Bethlehem's city,\nat the hour of middle-night,\nwas not sweet the brave song of the angels\nfor the King who was born that night?\n\nO King of Kings, a thousand glories to Thee,\nit is Thou who didst bear the cross\nout to Calvary's hill,\nand Thou wounded in every spot.\nWe will take courage from the pouring of the blood,\nand we will follow our Saviour,\nour Lord and our King,\nto the city of Glory,\nalong with the throng,\nSaints, Apostles, and Angels,\nto the dwelling of God's Son.","note":"A folk hymn from Bethlehem to Calvary to the city of glory.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-rest-with-thee","title":"I Rest With Thee, O Jesus","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["evening","dying","peace"],"text":"I rest with Thee, O Jesus,\nAnd do Thou rest with me.\nThe oil of Christ on my poor soul,\nThe creed of the Twelve to make me whole,\nAbove my head I see.\nO Father, who created me,\nO Son, who purchased me,\nO Spirit Blest, who blessest me,\nRest ye with me.","note":"A bedtime prayer to the Father, Son, and Spirit, also lovely at the bedside of the dying.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-thanks-after-food","title":"Thanksgiving After Food","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["gratitude","daily","home"],"text":"Great Giver of the open hand,\nWe stand to thank Thee for our meat,\nA hundred praises, Christ, 'tis meet,\nFor all we drink, for all we eat.","note":"A four line Irish grace after a meal.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-sacred-trinity","title":"The Sacred Trinity","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"poem","occasion":["daily"],"text":"Three folds of the cloth, yet one only napkin is there,\nThree joints in the finger, but still only one finger fair;\nThree leaves of the shamrock, yet no more than one shamrock to wear.\nFrost, snow-flakes and ice, all in water their origin share,\nThree Persons in God; to one God alone we make prayer.","note":"The three in one shown in a napkin, a finger, and the shamrock, as Patrick is said to have taught.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-king-of-wounds","title":"O King of the Wounds","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["dying","comfort"],"text":"O King of the Wounds! who found death on the top of the tree,\nBy the hand of the blind was Thy heart's blood riven from Thee;\nBy the blood from Thy wounds flowing down in a pool on the field,\nO bear us to Paradise, Thou, 'neath the shade of Thy shield.","note":"A short Passion prayer asking to be carried to Paradise.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-before-sleep","title":"Prayer Before Going to Sleep","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","peace"],"text":"The cross of the angels\nOn the bed where I lie;\nThe robe of the kingdom,\nMay it come very nigh;\nO Glorious Virgin,\nMy thousand loves thou,\nMy helpful supporter,\nMy affection thou.\nMy woman-physician,\nIll or well, thou,\nMy firm faithful helper\nIn the Kingdom of graces, thou. O gentle Jesus, O Jesus, most gentle,\nO Jesus Christ, have mercy upon us;\nO glorious Virgin, pray thou also for us;\nO Mother of God, O Bright Star of Knowledge,\nO Queen of Paradise, watch thou and ward us,\nThe light of glory obtain from thy Child for us,\nA sight of thy house, by thy great power's might, for us\nThe Light of all lights, and a sight of the Trinity,\nAnd the grace of long patience in days of adversity.","note":"An Irish night prayer to Jesus and Mary for a peaceful bed and patience in hard days.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-lie-down-with-god","title":"I Lie Down With God","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","peace"],"text":"I lie down with God, and may God lie down with me;\nThe right hand of God under my head,\nThe two hands of Mary round about me,\nThe cross of the nine white angels,\nFrom the back of my head\nTo the sole of my feet.\nMay I not lie with evil,\nAnd may evil not lie with me.\nAnna, mother of Mary,\nMary, mother of Christ,\nElizabeth, mother of John Baptist,\nI myself beseech these three\nTo keep the couch free from sickness.\nThe tree on which Christ suffered\nBe between me and the heavy-lying (nightmare),\nAnd any other thing that seeks my harm.\nWith the will of God and the aid of the glorious Virgin.","note":"An Irish folk night prayer with the hand of God under the head and the arms of Mary around.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-white-paternoster","title":"The White Paternoster","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","dying","peace"],"text":"I myself lie down with God,\nMay God lie down with me!\nThe protection of God above my head,\nAnd the cross of the angels beneath my body.\nWhere wilt thou lie down to-night?\nBetween Mary and her Son,\nBetween Brigit and her mantle,\nBetween Columcille and his shield,\nBetween God and His right hand.\nWhere wilt thou arise on the morrow?\nI will arise with Patrick.\nWho are they in front of us?\nTwo hundred angels.\nWho are they behind us?\nAs many again of the people of God.\nShut the forts of hell,\nAnd open the gates of the kingdom of God.\nLet the mighty radiance out,\nAnd lead the sorrowful soul within.\nO God, have mercy upon us!\nO Son of the Virgin, may our souls be found by thee!","note":"Said on lying down to sleep, with Mary, Brigid, Columba, and two hundred angels around the bed; also used at the bedside of the dying.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-between-you-and-grief","title":"From the White Paternoster: Between You and Each Grief","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"blessing","occasion":["grief","comfort","funeral"],"text":"O Men of the World who are shedding tears,\nI put Mary with her Son between you and your fears,\nBrigit with her mantle,\nMichael with his shield,\nAnd the two long white hands of God from behind folding us all,\nBetween you and each grief\nAll the years,\nFrom this night till a year from to-night,\nAnd this night itself, with God.","note":"The close of a folk night prayer that places Mary, Brigid, Michael, and the hands of God between the mourners and their sorrow.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-night-prayer","title":"A Night Prayer","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["evening","dying","peace"],"text":"May the will of God be done by us,\nMay the death of the saints be won by us,\nAnd the light of the kingdom begun in us;\nMay Jesus, the Child, be beside my bed,\nMay the Lamb of mercy uplift my head,\nMay the Virgin her heavenly brightness shed,\nAnd Michael be steward of my soul!","note":"Seven lines asking for the death of the saints, the Child at the bedside, and Michael as steward of the soul.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-safeguarding","title":"The Safe-Guarding of My Soul","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying","evening"],"text":"The safe-guarding of my soul be Thine,\nO Father Ever-mighty;\nO Blessed Mary,\nNurse of the King of Glory;\nMichael the angel,\nTheir peaceful messenger,\nThe twelve apostles, and\nThe Lord of Mercy,\nSo that they may be\nSafe-guarding my soul\nUnto the city of Glory.","note":"A short commendation of the soul to the Father, Mary, Michael, and the apostles.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-lie-on-this-bed","title":"I Lie on This Bed (A Night Confession)","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["evening","forgiveness","dying"],"text":"I lie on this bed\nAs I lie in the tomb.\nFirmly, O Jesus,\nI make my confession to Thee.\nThrough deeds of my flesh,\nThrough thoughts of my heart,\nThrough sight of my eyes,\nThrough hearing of my ears,\nThrough speech of my lips,\nThrough movements of my feet,\nThrough everything spoken\nWhich was not true;\nThrough each thing promised\nAnd not fulfilled;\nEach thing that I did against Thy law,\nOr against Thy sacred will,\nI ask forgiveness from Thee, O King of Glory.","note":"An honest examen at bedtime, naming each sense and asking forgiveness of the King of Glory.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-straying-sheep","title":"The Straying Sheep","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["healing","comfort"],"text":"Fair Jesu, guide Thy straying sheep\nAlong the fragrant valleys,\nAnd where the meadow-grass grows deep,\nGuard from the wild wolf's sallies;\nNo sickness unto death be theirs,\nBut sickness unto healing,\nOur sickness be for love to Thee\nO King of all the living.","note":"A prayer for the sick: sickness unto healing, guided by Jesus as a shepherd.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-before-communion","title":"Before Communion","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["forgiveness","daily"],"text":"O Saviour, who lightest the sun's blessed ray,\nRemit my offences, this day and alway,\nAbove my deserving, or all I could pay;\nThen with joy I receive my Redeemer to-day.","note":"Four lines said before receiving communion, also at a bedside communion.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-sweet-name","title":"May the Sweet Name of Jesus","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["daily","peace"],"text":"May the sweet name of Jesus\nBe lovingly graven\nIn my heart's inmost haven.\n\nO Mary, Blest Mother,\nBe Jesus my Brother,\nAnd I Jesu's lover.\n\nA binding of love\nThat no distance can sever,\nBe between us for ever.\nYea, O my Saviour,\nFor ever and ever.","note":"A binding of love that no distance can sever.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-o-blessed-jesus","title":"O Blessed Jesus","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying","comfort"],"text":"O Blessed Jesus, and O Nurse of the fair white Lamb,\nIn the dread hour of death it is under your shelter I am;\nSaints and angels about me in every time, in all places,\nLeading my soul to the home of the King of the Graces.","note":"Four lines for the hour of death, with saints and angels leading the soul home.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-friends-of-my-soul","title":"O Jesus, and Mary","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"prayer","occasion":["dying","comfort"],"text":"O Jesus, and Mary who fostered the King of Grace,\nBe ye the friends of my soul, in every time and place,\nCold as a stone lies my soul, unheeding the things above,\nSmooth Thou my path in Thy time, Lord of my love.","note":"A second version of the same prayer, asking Jesus and Mary to be friends of the soul.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-morning-wish","title":"Morning Wish","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"prayer","occasion":["morning","daily"],"text":"O Jesu, in the morning, I cry and call on Thee,\nBlessed only Son who hast purchased us dearly;\nSafeguard my soul under the protection of Thy holy cross,\nMay sin and loss be kept from me through the course of this day.","note":"A morning prayer under the protection of the cross.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-covering-fire","title":"On Covering the Fire for the Night","by":"Traditional, Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic","christian"],"denom":["irish"],"type":"blessing","occasion":["evening","home"],"text":"Let us preserve this fire, as Christ preserves all,\nChrist at the top of this house and Brigit in the midst;\nThe twelve apostles of greatest power in the heavens\nGuarding and preserving this house till day.","note":"Said while banking the peat fire at night to keep its seed till morning, with Christ above the house and Brigid in the midst.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-three-holy-words","title":"The Merciful Word, the Singing Word, and the Good Word","by":"Traditional, Irish","tr":"Lady Wilde","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"blessing","occasion":["blessing","peace"],"text":"Three things are of the Evil One, An evil eye, An evil tongue, An evil mind;\nThree things are of God, and these three are what Mary told to her Son, for she heard them in heaven, The merciful word, The singing word, And the good word.\nMay the power of these three holy things be on all the men and women of Erin for evermore.","note":"An Irish folk blessing that sets three things of God against three things of evil, ending in a blessing on all the people of Erin.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-charm-sorrow","title":"A Charm for Sorrow","by":"Traditional, Irish","tr":"Lady Wilde","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"blessing","occasion":["grief","comfort"],"text":"A Charm set by Mary for her Son, before the fair man and the turbulent woman laid Him in the grave.\n\nThe charm of Michael with the shield,\nOf the palm-branch of Christ,\nOf Brigit with her veil.\n\nThe charm which God set for Himself when the divinity within Him was darkened.\n\nA charm to be said by the cross when the night is black and the soul is heavy with sorrow.\n\nA charm to be said at sunrise, with the hands on the breast, when the eyes are red with weeping, and the madness of grief is strong. A charm that has no words, only the silent prayer.","note":"An Irish folk charm said with hands on the breast in deep grief, ending in a silent prayer.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-keening-mary","title":"The Keening of Mary","by":"Traditional, Irish","tr":"P. H. Pearse","year":1913,"trad":["celtic","christian","catholic"],"denom":["irish"],"type":"chant","occasion":["grief","season"],"text":"\"O Peter, O Apostle, hast thou seen my bright love?\"\nM'ochon agus m'ochon, O!\n\"I saw Him even now in the midst of His foemen,\"\nM'ochon agus m'ochon, O!\n\n\"Come hither, two Marys, till ye keen my bright love.\"\nM'ochon agus m'ochon, O!\n\"What have we to keen if we keen not His bones?\"\nM'ochon agus m'ochon, O!\n\n\"Who is that stately man on the tree of the Passion?\"\nM'ochon agus m'ochon, O!\n\"Dost thou not know thy Son, O Mother?\"\nM'ochon agus m'ochon, O!\n\n\"And is that the little Son I carried nine months?\nM'ochon agus m'ochon, O!\n\"And is that the little Son that was born in the stable?\nM'ochon agus m'ochon, O!\n\n\"And is that the little Son that was nursed at Mary's breast?\"\nM'ochon agus m'ochon, O!\n\"Hush, O Mother, and be not sorrowful.\"\nM'ochon agus m'ochon, O!\n\n\"And is that the hammer that struck home nails through Thee?\nM'ochon agus m'ochon, O!\n\"And is that the spear that went through Thy white side?\nM'ochon agus m'ochon, O!\n\n\"And is that the crown of thorns that crowned Thy beauteous head?\"\nM'ochon agus m'ochon, O!\n\"Hush, O Mother, be not sorrowful.\nM'ochon agus m'ochon, O!\n\n\"Hush, O Mother, and be not sorrowful,\nM'ochon agus m'ochon, O!\n\"The women of my keening are yet unborn, little Mother.\"\nM'ochon agus m'ochon, O!\n\n\"O woman, who weepest by this My death,\nM'ochon agus m'ochon, O!\n\"There will be hundreds to-day in the Garden of Paradise!\"\nM'ochon agus m'ochon, O!","note":"A Good Friday keen in which Mary mourns her Son, taken down from Mary Clancy of Moycullen; for deep grief and Holy Week.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-newborn","title":"Greeting to the New-Born Babe","by":"Traditional, Old Irish","tr":"Eleanor Hull","year":1913,"trad":["celtic"],"denom":["irish"],"type":"blessing","occasion":["birth","celebration"],"text":"Welcome, little stranger,\nBorn in pain and danger,\nHe will be our gracious Lord,\nSon of gentle Cathva.\n\nSon of gentle Cathva,\nFrom the fort of Brug na Brat;\nSon of valorous Ness the Young,\nMy son, and my grandson.\n\nMy son, and my grandson,\nOf the world the shining One,\nHe of old Rath Line the king,\nPoet-prince, my offspring.\n\nPoet-prince, my offspring,\nOverseas thy hosts thou wilt fling;\nLittle songster from the Brug,\nLittle kid, we welcome you.","note":"An old Irish welcome to a new baby, from the birth tale of King Conchobar.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-amorgen","title":"From Amorgen's Song","by":"Traditional, Old Irish (attributed to the poet Amorgen)","tr":"Eleanor Hull, after John MacNeill","year":1913,"trad":["celtic","pagan","nature"],"denom":["irish"],"type":"chant","occasion":["nature"],"text":"I am the wind on the sea (for depth);\nI am a wave of the deep (for weight);\nI am the sound of the sea (for horror);\nI am a stag of seven points (? for strength);\nI am a hawk on a cliff (for deftness);\nI am a tear of the sun (for clearness);\nI am the fairest of herbs;\nI am a boar for valour;\nI am a salmon in a pool (i.e. the pools of knowledge);\nI am a lake on a plain (for extent);\nI am a hill of Poetry (and knowledge);","note":"The oldest voice of Irish poetry, the poet naming himself in the wind, the wave, and the salmon.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-praise-of-may","title":"In Praise of May","by":"Ascribed to Fionn mac Cumhaill","tr":"T. W. Rolleston","year":1913,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["season","nature","celebration"],"text":"May-day! delightful day!\nBright colours play the vale along.\nNow wakes at morning's slender ray\nWild and gay the blackbird's song.\n\nNow comes the bird of dusty hue,\nThe loud cuckoo, the summer-lover;\nBranchy trees are thick with leaves;\nThe bitter, evil time is over.\n\nSwift horses gather nigh\nWhere half dry the river goes;\nTufted heather clothes the height;\nWeak and white the bogdown blows.\n\nCorncrake sings from eve to morn,\nDeep in corn, a strenuous bard!\nSings the virgin waterfall,\nWhite and tall, her one sweet word.\n\nLoaded bees with puny power\nGoodly flower-harvest win;\nCattle roam with muddy flanks;\nBusy ants go out and in.\n\nThrough the wild harp of the wood\nMaking music roars the gale:\nNow it settles without motion,\nOn the ocean sleeps the sail.\n\nMen grow mighty in the May,\nProud and gay the maidens grow;\nFair is every wooded height;\nFair and bright the plain below.\n\nA bright shaft has smit the streams,\nWith gold gleams the water-flag;\nLeaps the fish, and on the hills\nArdour thrills the leaping stag.\n\nLoudly carols the lark on high,\nSmall and shy, his tireless lay,\nSinging in wildest, merriest mood,\nDelicate-hued, delightful May.","note":"The Fenian May song, for May Day and the beginning of summer.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-grainne-sleep","title":"From the Sleep-Song of Grainne","by":"Traditional, Irish (from the Poem-Book of Fionn)","tr":"Eleanor Hull","year":1913,"trad":["celtic"],"denom":["irish"],"type":"song","occasion":["wedding","evening","peace"],"text":"Sleep a little, a little little, thou needest feel no fear or dread,\nYouth to whom my love is given, I am watching near thy head.\nSleep a little, with my blessing, Dermuid of the lightsome eye,\nI will guard thee as thou dreamest, none shall harm while I am by.\n\nSleep as Degha, who in triumph, ere the sun sank o'er the land,\nStole the maiden he had craved for, plucked her from fierce Deacall's hand.\n\nYet, O Dermuid, sleep a little, this one night our fear hath fled,\nYouth to whom my love is given, see, I watch beside thy bed.","note":"Grainne watches over her beloved as he sleeps; a love song for a wedding or a quiet evening.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-exiles-song","title":"The Exile's Song","by":"MacAmbrois, an Irish emigrant","tr":"Eleanor Hull","year":1913,"trad":["celtic"],"denom":["irish"],"type":"song","occasion":["home","grief","dying"],"text":"Oh! were I again on my native bay,\nBy the curving hills that are far away,\nI scarcely would wander for half a day\nFrom the Cuckoo's Glen of a Sunday!\nFor, och, och, Eire, O!\nLone is the exile from Eire, O!\n'Tis my heart that is heavy and weary!\n\nO many a Christmas in Ireland,\nI would race with the boys on the pleasant strand,\nWith my hurling-stick in my baby hand,\nAnd but little sense to guide me!\nAnd, och, och, Eire, O!\nSad is the exile from Eire, O!\n'Tis my heart that is heavy and weary!\n\nLonely and drear is this foreign plain,\nWhere I hear but my own voice back again,\nNo call of the corncrake, cuckoo, or crane,\nNow awakens me on a Sunday!\nThen, och, och, Eire, O!\nLost is the exile from Eire, O!\n'Tis my heart that is heavy and weary!\n\nO, had I a boat and a single oar,\nWith the help of God I'd reach Erin's shore,\nNay, the very tide might drift me o'er,\nTo die at home in Erin!\nNow, och, och, Eire, O!\nWould I were back in Eire, O!\n'Tis my heart that is heavy and weary!","note":"An emigrant longs for the strand and glen of home; for those far from home or wishing to die at home.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-first-winter","title":"First Winter-Song","by":"Traditional, Old Irish","tr":"Alfred Perceval Graves","year":1913,"trad":["celtic","nature"],"denom":["irish"],"type":"poem","occasion":["season","nature"],"text":"Take my tidings!\nStags contend;\nSnows descend:\nSummer's end!\n\nA chill wind raging;\nThe sun low keeping,\nSwift to set\nO'er seas high sweeping.\n\nDull red the fern;\nShapes are shadows:\nWild geese mourn\nO'er misty meadows.\n\nKeen cold limes\nEach weaker wing.\nIcy times:\nSuch I sing!\nTake my tidings!","note":"Graves's rhyming version of the ancient tidings of winter.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-fishermans-keen","title":"The Fisherman's Keen","by":"Traditional, Irish","tr":"Anonymous","year":1913,"trad":["celtic"],"denom":["irish"],"type":"poem","occasion":["grief","funeral"],"text":"O loudly wailed the winter wind, the driving sleet fell fast,\nThe ocean billow wildly heaved beneath the bitter blast;\nMy three fair sons, ere break of day, to fish had left the shore,\nThe tempest came forth in its wrath, they ne'er returned more.\n\nCormac, 'neath whose unerring aim the wild duck fell in flight,\nThe plover of the lonesome hills, the curlew swift as light!\nMy firstborn child! the flower of youth! the dearest and the best!\nO would that thou wert spared to me, though I had lost the rest!\n\nAnd thou, my handsome Felix! in whose eye so dark and bright\nThe soul of courage and of wit looked forth in laughing light!\nAnd Daniel, too, my fair-haired boy, the gentle and the brave,\nAll, all my stately sons were 'whelmed beneath the foaming wave.\n\nUpon the shore, in wild despair, your aged father stood,\nAnd gazed upon his Daniel's corse, too late snatched from the flood!\nI saw him pale and lifeless lie, no more to see the light:\nAnd cold, and dumb, and motionless, my heart grew at the sight!\n\nMy children, my loved children! do you view my bitter grief?\nLook down upon your poor old sire, whose woe knows no relief!\nThe sunshine of mine eyes is gone, the comfort of my heart;\nMy life of life, my soul of soul, I've seen from earth depart!\n\nWhat am I now? an aged man, to earth by sorrow bowed,\nI weep within a stranger's home; lone, even in a crowd;\nThere is no sorrow like to mine, no grief like mine appears,\nMy once blithe Christmas is weighed down with anguish and with tears.\n\nMy sons! my sons! abandoned to the fury of the waves!\nWould I could reach the two who lie in ocean's darksome caves;\n'Twould bring some comfort to my heart in earth to see them laid,\nAnd hear in Affadown the wild lamentings for them made.\n\nO would that like the gay \"Wild Geese\" my sons had left this land,\nFrom their poor father in his age, to seek a foreign strand;\nThen might I hope the Lord of Heaven in mercy would restore,\nMy brave and good and stately sons in time to me once more!","note":"A father mourns three sons lost at sea; for loss by drowning or the death of a child.","voice":"brian","source":{"name":"The Poem-Book of the Gael, ed. Eleanor Hull (1913)","url":"https://www.gutenberg.org/ebooks/46917"},"rights":"pd","pd":"published 1913 in London; US public domain (published before 1930)"},{"id":"celt-caedmon-hymn","title":"Caedmon's Hymn","by":"Caedmon of Whitby","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"hymn","occasion":["daily","gratitude","nature"],"text":"Now must we praise the Maker of the heavenly kingdom, the power of the Creator and His counsel, the deeds of the Father of glory. How He, being the eternal God, became the Author of all wondrous works, Who being the Almighty Guardian of the human race, first created heaven for the sons of men to be the covering of their dwelling place, and next the earth.","note":"The first hymn known in English, given in a dream to the cowherd Caedmon at Hilda's abbey; Bede gives its sense in prose.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-caedmon-gift","title":"Caedmon and the Gift of Song","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"story","occasion":["daily","hope"],"text":"There was in the monastery of this abbess a certain brother, marked in a special manner by the grace of God, for he was wont to make songs of piety and religion, so that whatever was expounded to him out of Scripture, he turned ere long into verse expressive of much sweetness and penitence, in English, which was his native language. By his songs the minds of many were often fired with contempt of the world, and desire of the heavenly life. Others of the English nation after him attempted to compose religious poems, but none could equal him, for he did not learn the art of poetry from men, neither was he taught by man, but by God's grace he received the free gift of song, for which reason he never could compose any trivial or vain poem, but only those which concern religion it behoved his religious tongue to utter. For having lived in the secular habit till he was well advanced in years, he had never learned anything of versifying; and for this reason sometimes at a banquet, when it was agreed to make merry by singing in turn, if he saw the harp come towards him, he would rise up from table and go out and return home.\n\nOnce having done so and gone out of the house where the banquet was, to the stable, where he had to take care of the cattle that night, he there composed himself to rest at the proper time. Thereupon one stood by him in his sleep, and saluting him, and calling him by his name, said, \"Caedmon, sing me something.\" But he answered, \"I cannot sing, and for this cause I left the banquet and retired hither, because I could not sing.\" Then he who talked to him replied, \"Nevertheless thou must needs sing to me.\" \"What must I sing?\" he asked. \"Sing the beginning of creation,\" said the other. Having received this answer he straightway began to sing verses to the praise of God the Creator, which he had never heard, the purport whereof was after this manner: \"Now must we praise the Maker of the heavenly kingdom, the power of the Creator and His counsel, the deeds of the Father of glory. How He, being the eternal God, became the Author of all wondrous works, Who being the Almighty Guardian of the human race, first created heaven for the sons of men to be the covering of their dwelling place, and next the earth.\" This is the sense but not the order of the words as he sang them in his sleep; for verses, though never so well composed, cannot be literally translated out of one language into another without loss of their beauty and loftiness. Awaking from his sleep, he remembered all that he had sung in his dream, and soon added more after the same manner, in words which worthily expressed the praise of God.","note":"How a shy cowherd who could not sing was given the gift of song; for anyone who feels they have nothing to offer.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-caedmon-death","title":"The Death of Caedmon","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"story","occasion":["dying","peace"],"text":"For when the hour of his departure drew near, it was preceded by a bodily infirmity under which he laboured for the space of fourteen days, yet it was of so mild a nature that he could talk and go about the whole time. In his neighbourhood was the house to which those that were sick, and like to die, were wont to be carried. He desired the person that ministered to him, as the evening came on of the night in which he was to depart this life, to make ready a place there for him to take his rest. The man, wondering why he should desire it, because there was as yet no sign of his approaching death, nevertheless did his bidding. When they had lain down there, and had been conversing happily and pleasantly for some time with those that were in the house before, and it was now past midnight, he asked them, whether they had the Eucharist within? They answered, \"What need of the Eucharist? for you are not yet appointed to die, since you talk so merrily with us, as if you were in good health.\" \"Nevertheless,\" said he, \"bring me the Eucharist.\" Having received It into his hand, he asked, whether they were all in charity with him, and had no complaint against him, nor any quarrel or grudge. They answered, that they were all in perfect charity with him, and free from all anger; and in their turn they asked him to be of the same mind towards them. He answered at once, \"I am in charity, my children, with all the servants of God.\" Then strengthening himself with the heavenly Viaticum, he prepared for the entrance into another life, and asked how near the time was when the brothers should be awakened to sing the nightly praises of the Lord? They answered, \"It is not far off.\" Then he said, \"It is well, let us await that hour;\" and signing himself with the sign of the Holy Cross, he laid his head on the pillow, and falling into a slumber for a little while, so ended his life in silence.\n\nThus it came to pass, that as he had served the Lord with a simple and pure mind, and quiet devotion, so he now departed to behold His Presence, leaving the world by a quiet death; and that tongue, which had uttered so many wholesome words in praise of the Creator, spake its last words also in His praise, while he signed himself with the Cross, and commended his spirit into His hands;","note":"Caedmon asks if all are at peace with him, then falls asleep before the night office; a gentle story of a good death.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-sparrow","title":"The Sparrow in the Hall","by":"Bede, the words of a counselor of King Edwin","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian","all"],"denom":["northumbrian"],"type":"reflection","occasion":["dying","grief","hope"],"text":"The present life of man upon earth, O king, seems to me, in comparison with that time which is unknown to us, like to the swift flight of a sparrow through the house wherein you sit at supper in winter, with your ealdormen and thegns, while the fire blazes in the midst, and the hall is warmed, but the wintry storms of rain or snow are raging abroad. The sparrow, flying in at one door and immediately out at another, whilst he is within, is safe from the wintry tempest; but after a short space of fair weather, he immediately vanishes out of your sight, passing from winter into winter again. So this life of man appears for a little while, but of what is to follow or what went before we know nothing at all. If, therefore, this new doctrine tells us something more certain, it seems justly to deserve to be followed.\"","note":"A Northumbrian counselor's famous picture of life as a sparrow's flight through a warm hall, read at funerals of every faith and none.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-aidan-life","title":"Saint Aidan of Lindisfarne","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["irish","northumbrian"],"type":"story","occasion":["daily"],"text":"From this island, then, and the fraternity of these monks, Aidan was sent to instruct the English nation in Christ, having received the dignity of a bishop. At that time Segeni, abbot and priest, presided over that monastery. Among other lessons in holy living, Aidan left the clergy a most salutary example of abstinence and continence; it was the highest commendation of his doctrine with all men, that he taught nothing that he did not practise in his life among his brethren; for he neither sought nor loved anything of this world, but delighted in distributing immediately among the poor whom he met whatsoever was given him by the kings or rich men of the world. He was wont to traverse both town and country on foot, never on horseback, unless compelled by some urgent necessity; to the end that, as he went, he might turn aside to any whomsoever he saw, whether rich or poor, and call upon them, if infidels, to receive the mystery of the faith, or, if they were believers, strengthen them in the faith, and stir them up by words and actions to giving of alms and the performance of good works.","note":"Bede on the Irish monk from Iona who walked everywhere, gave everything to the poor, and taught by his life.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-aidan-gentle","title":"Saint Aidan and the Milk of Easier Teaching","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["irish","northumbrian"],"type":"story","occasion":["daily"],"text":"It is said, that when King Oswald had asked a bishop of the Scots to administer the Word of faith to him and his nation, there was first sent to him another man of more harsh disposition, who, after preaching for some time to the English and meeting with no success, not being gladly heard by the people, returned home, and in an assembly of the elders reported, that he had not been able to do any good by his teaching to the nation to whom he had been sent, because they were intractable men, and of a stubborn and barbarous disposition. They then, it is said, held a council and seriously debated what was to be done, being desirous that the nation should obtain the salvation it demanded, but grieving that they had not received the preacher sent to them. Then said Aidan, who was also present in the council, to the priest in question, \"Methinks, brother, that you were more severe to your unlearned hearers than you ought to have been, and did not at first, conformably to the Apostolic rule, give them the milk of more easy doctrine, till, being by degrees nourished with the Word of God, they should be capable of receiving that which is more perfect and of performing the higher precepts of God.\" Having heard these words, all present turned their attention to him and began diligently to weigh what he had said, and they decided that he was worthy to be made a bishop, and that he was the man who ought to be sent to instruct the unbelieving and unlearned; since he was found to be endued preeminently with the grace of discretion, which is the mother of the virtues. So they ordained him and sent him forth to preach; and, as time went on, his other virtues became apparent, as well as that temperate discretion which had marked him at first.","note":"Why the gentle Aidan was chosen: begin with kindness, and grow people slowly; a story for teachers, chaplains, and parents.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-aidan-horse","title":"Saint Aidan and the King's Horse","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["irish","northumbrian"],"type":"story","occasion":["daily","gratitude"],"text":"He had given a beautiful horse to Bishop Aidan, to use either in crossing rivers, or in performing a journey upon any urgent necessity, though the Bishop was wont to travel ordinarily on foot. Some short time after, a poor man meeting the Bishop, and asking alms, he immediately dismounted, and ordered the horse, with all his royal trappings, to be given to the beggar; for he was very compassionate, a great friend to the poor, and, in a manner, the father of the wretched. This being told to the king, when they were going in to dinner, he said to the Bishop, \"What did you mean, my lord Bishop, by giving the poor man that royal horse, which it was fitting that you should have for your own use? Had not we many other horses of less value, or things of other sorts, which would have been good enough to give to the poor, instead of giving that horse, which I had chosen and set apart for your own use?\" Thereupon the Bishop answered, \"What do you say, O king? Is that son of a mare more dear to you than that son of God?\" Upon this they went in to dinner, and the Bishop sat in his place; but the king, who had come in from hunting, stood warming himself, with his attendants, at the fire. Then, on a sudden, whilst he was warming himself, calling to mind what the bishop had said to him, he ungirt his sword, and gave it to a servant, and hastened to the Bishop and fell down at his feet, beseeching him to forgive him; \"For from this time forward,\" said he, \"I will never speak any more of this, nor will I judge of what or how much of our money you shall give to the sons of God.\" The bishop was much moved at this sight, and starting up, raised him, saying that he was entirely reconciled to him, if he would but sit down to his meat, and lay aside all sorrow.","note":"Aidan gives a royal horse to a beggar on the road and the humbled king kneels to him; a story of generosity.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-aidan-death","title":"The Death of Saint Aidan","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["irish","northumbrian"],"type":"story","occasion":["dying"],"text":"When he was sick they set up a tent for him against the wall at the west end of the church, and so it happened that he breathed his last, leaning against a buttress that was on the outside of the church to strengthen the wall.","note":"Aidan dies leaning against the wall of a small church, in a tent set up for him outside.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-hilda","title":"Saint Hilda, Whom All Called Mother","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"story","occasion":["dying","healing","peace"],"text":"When she had governed this monastery many years, it pleased Him Who has made such merciful provision for our salvation, to give her holy soul the trial of a long infirmity of the flesh, to the end that, according to the Apostle's example, her virtue might be made perfect in weakness. Struck down with a fever, she suffered from a burning heat, and was afflicted with the same trouble for six years continually; during all which time she never failed either to return thanks to her Maker, or publicly and privately to instruct the flock committed to her charge; for taught by her own experience she admonished all men to serve the Lord dutifully, when health of body is granted to them, and always to return thanks faithfully to Him in adversity, or bodily infirmity. In the seventh year of her sickness, when the disease turned inwards, her last day came, and about cockcrow, having received the voyage provision of Holy Housel, and called together the handmaids of Christ that were within the same monastery, she admonished them to preserve the peace of the Gospel among themselves, and with all others; and even as she spoke her words of exhortation, she joyfully saw death come, or, in the words of our Lord, passed from death unto life.","note":"Hilda of Whitby, trained by Aidan, gave thanks through six years of illness and died urging peace among all.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-hilda-teaching","title":"Saint Hilda's House of Peace","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"story","occasion":["daily","peace"],"text":"When she had for some years governed this monastery, wholly intent upon establishing a rule of life, it happened that she also undertook either to build or to set in order a monastery in the place called Streanaeshalch, and this work which was laid upon her she industriously performed; for she put this monastery under the same rule of monastic life as the former; and taught there the strict observance of justice, piety, chastity, and other virtues, and particularly of peace and charity; so that, after the example of the primitive Church, no one there was rich, and none poor, for they had all things common, and none had any private property. Her prudence was so great, that not only meaner men in their need, but sometimes even kings and princes, sought and received her counsel; she obliged those who were under her direction to give so much time to reading of the Holy Scriptures, and to exercise themselves so much in works of justice, that many might readily be found there fit for the priesthood and the service of the altar.","note":"How Hilda taught justice, peace, and charity, so that none were rich and none poor, and kings sought her counsel.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-hilda-bell","title":"The Bell at Hilda's Passing","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"story","occasion":["dying","grief","comfort"],"text":"That same night it pleased Almighty God, by a manifest vision, to make known her death in another monastery, at a distance from hers, which she had built that same year, and which is called Hacanos. There was in that monastery, a certain nun called Begu, who, having dedicated her virginity to the Lord, had served Him upwards of thirty years in the monastic life. This nun was resting in the dormitory of the sisters, when on a sudden she heard in the air the well-known sound of the bell, which used to awake and call them to prayers, when any one of them was taken out of this world, and opening her eyes, as she thought, she saw the roof of the house open, and a light shed from above filling all the place. Looking earnestly upon that light, she saw the soul of the aforesaid handmaid of God in that same light, being carried to heaven attended and guided by angels. Then awaking, and seeing the other sisters lying round about her, she perceived that what she had seen had been revealed to her either in a dream or a vision; and rising immediately in great fear, she ran to the virgin who then presided in the monastery in the place of the abbess, and whose name was Frigyth, and, with many tears and lamentations, and heaving deep sighs, told her that the Abbess Hilda, mother of them all, had departed this life, and had in her sight ascended to the gates of eternal light, and to the company of the citizens of heaven, with a great light, and with angels for her guides.","note":"A sister far away hears the bell and sees Hilda carried in light by angels; a comfort for those who could not be present.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-chad","title":"Saint Chad and the Song of Angels","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"story","occasion":["dying","comfort"],"text":"One day, when he was thus employed abroad, his companions having gone to the church, as I began to tell, and the bishop was alone reading or praying in the oratory of that place, on a sudden, as he afterwards said, he heard a sweet sound of singing and rejoicing descend from heaven to earth. This sound he said he first heard coming from the sky in the south-east, above the winter sunrise, and that afterwards it drew near him gradually, till it came to the roof of the oratory where the bishop was, and entering therein, filled all the place and encompassed it about. He listened attentively to what he heard, and after about half an hour, perceived the same song of joy to ascend from the roof of the said oratory, and to return to heaven in the same way as it came, with unspeakable sweetness. When he had stood some time amazed, and earnestly considering in his mind what this might be, the bishop opened the window of the oratory, and making a sound with his hand, as he was often wont to do, bade anyone who might be without to come in to him. He went hastily in, and the bishop said to him, \"Make haste to the church, and cause those seven brothers to come hither, and do you come with them.\" When they were come, he first admonished them to preserve the virtue of love and peace among themselves, and towards all the faithful; and with unwearied earnestness to follow the rules of monastic discipline, which they had either been taught by him, and had seen him observe, or had found in the words and actions of the former fathers. Then he added that the day of his death was at hand; for, said he, \"that gracious guest, who was wont to visit our brethren, has vouchsafed also to come to me this day, and to call me out of this world. Return, therefore, to the church, and speak to the brethren, that in their prayers they commend my departure to the Lord, and that they be mindful to prepare for their own, the hour whereof is uncertain, by watching, and prayer, and good works.\"\n\nWhen he had spoken thus much and more to the same end, and they, having received his blessing, had gone away in great sorrow, he who had heard the heavenly song returned alone, and prostrating himself on the ground, said, \"I beseech you, father, may I be permitted to ask a question?\", \"Ask what you will,\" answered the bishop. Then he said, \"I beseech you to tell me what was that song which I heard as of a joyful company coming from heaven upon this oratory, and after some time returning to heaven?\" The bishop answered: \"If you heard the singing, and know of the coming of the heavenly company, I command you, in the Name of the Lord, that you tell it not to any before my death. But in truth they were angelic spirits, who came to call me to my heavenly reward, which I have always loved and longed after, and they promised that they would return seven days hence, and take me away with them.\" Which was indeed fulfilled, as had been said to him; for being presently seized with bodily infirmity, and the same daily increasing, on the seventh day, as had been promised to him, when he had prepared for death by receiving the Body and Blood of our Lord, his saintly soul being delivered from the prison of the body, led, as may justly be believed, by the attendant angels, he departed to the joys of Heaven.","note":"Chad, a student of Aidan, hears the angels' song and readies his brothers for his death seven days later.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-cuthbert-herebert","title":"Saint Cuthbert and Herebert, Soul Friends","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"story","occasion":["dying","grief","comfort"],"text":"There was a certain priest, called Herebert, a man of holy life, who had long been united with the man of God, Cuthbert, in the bonds of spiritual friendship. This man leading a solitary life in the island of that great lake from which the river Derwent flows at its beginning, was wont to visit him every year, and to receive from him the teaching of everlasting salvation. Hearing that Bishop Cuthbert was come to the city of Lugubalia, he went thither to him, according to his custom, seeking to be more and more inflamed in heavenly desires through his wholesome admonitions. Whilst they alternately entertained one another with draughts of the celestial life, the bishop, among other things, said, \"Brother Herebert, remember at this time to ask me and speak to me concerning all whereof you have need to ask and speak; for, when we part, we shall never again see one another with bodily eyesight in this world. For I know of a surety that the time of my departure is at hand, and that shortly I must put off this my tabernacle.\" Hearing these words, Herebert fell down at his feet, with tears and lamentations, and said, \"I beseech you, by the Lord, not to forsake me; but to remember your most faithful companion, and entreat the mercy of God that, as we have served Him together upon earth, so we may depart together to behold His grace in Heaven. For you know that I have always endeavoured to live according to the words of your lips, and likewise whatsoever faults I have committed, either through ignorance or frailty, I have instantly sought to amend according to the judgement of your will.\" The bishop applied himself to prayer, and having presently had intimation in the spirit that he had obtained what he asked of the Lord, he said, \"Rise, brother, and do not weep, but rejoice greatly because the mercy of Heaven has granted what we desired.\"\n\nThe event established the truth of this promise and prophecy, for after their parting, they never again saw one another in the flesh; but their spirits quitting their bodies on one and the same day, to wit, the 20th of March, were immediately united in fellowship in the blessed vision, and together translated to the heavenly kingdom by the ministry of angels.","note":"Two friends ask to die on the same day, and do; a story of soul friendship for those who fear parting.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-cuthbert-farne","title":"Saint Cuthbert on Farne","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"story","occasion":["nature","daily"],"text":"When, after expelling the enemy, he had, with the help of the brethren, built himself a narrow dwelling, with a mound about it, and the necessary cells in it, to wit, an oratory and a common living room, he ordered the brothers to dig a pit in the floor of the room, although the ground was hard and stony, and no hopes appeared of any spring. When they had done this relying upon the faith and prayers of the servant of God, the next day it was found to be full of water, and to this day affords abundance of its heavenly bounty to all that resort thither. He also desired that instruments for husbandry might be brought him, and some wheat; but having prepared the ground and sown the wheat at the proper season, no sign of a blade, not to speak of ears, had sprouted from it by the summer. Hereupon, when the brethren visited him according to custom, he ordered barley to be brought him, if haply it were either the nature of the soil, or the will of God, the Giver of all things, that such grain rather should grow there. He sowed it in the same field, when it was brought him, after the proper time of sowing, and therefore without any likelihood of its bearing fruit; but a plentiful crop immediately sprang up, and afforded the man of God the means which he had desired of supporting himself by his own labour.","note":"Cuthbert finds water in hard ground and grows barley on his island hermitage.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-bede-death","title":"The Death of Bede","by":"Cuthbert of Jarrow, letter to Cuthwin","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"story","occasion":["dying","peace"],"text":"But they rejoiced for that he said, 'It is time for me, if it be my Maker's will, to be set free from the flesh, and come to Him Who, when as yet I was not, formed me out of nothing. I have lived long; and well has my pitiful judge disposed my life for me; the time of my release is at hand; for my soul longs to see Christ my King in His beauty.' Having said this and much more for our profit and edification, he passed his last day in gladness till the evening; and the aforesaid boy, whose name was Wilbert, still said, 'Dear master, there is yet one sentence not written.' He answered, 'It is well, write it.' Soon after, the boy said, 'Now it is written.' And he said, 'It is well, thou hast said truly, it is finished. Take my head in thy hands, for I rejoice greatly to sit facing my holy place where I was wont to pray, that I too, sitting there, may call upon my Father.' And thus on the pavement of his little cell, chanting 'Glory be to the Father, and to the Son, and to the Holy Ghost,' and the rest, he breathed his last.","note":"Bede finishes the last sentence of his translation, says it is finished, and dies singing the Glory Be on the floor of his cell.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-bede-death-song","title":"Bede's Death Song","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["northumbrian"],"type":"poem","occasion":["dying","peace"],"text":"Before the inevitable journey hence, no man is wiser than is needful that he may consider, ere the soul departs, what good or evil it hath done and how it shall be judged after its departure.","translit":"Fore then neidfaerae naenig uiuurthit","note":"Lines Bede sang in Old English as he lay dying, given here in prose.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-columba-comes","title":"Columba Comes to Iona","by":"Bede","tr":"A. M. Sellar","year":1907,"trad":["celtic","christian"],"denom":["irish","scottish"],"type":"story","occasion":["daily"],"text":"Columba came into Britain in the ninth year of the reign of Bridius, who was the son of Meilochon, and the powerful king of the Pictish nation, and he converted that nation to the faith of Christ, by his preaching and example. Wherefore he also received of them the gift of the aforesaid island whereon to found a monastery. It is not a large island, but contains about five families, according to the English computation; his successors hold it to this day; he was also buried therein, having died at the age of seventy-seven, about thirty-two years after he came into Britain to preach. Before he crossed over into Britain, he had built a famous monastery in Ireland, which, from the great number of oaks, is in the Scottish tongue called Dearmach, The Field of Oaks. From both these monasteries, many others had their beginning through his disciples, both in Britain and Ireland; but the island monastery where his body lies, has the pre-eminence among them all.","note":"Bede on how Columba came from Ireland to Iona and how its monasteries spread.","voice":"brian","source":{"name":"Bede's Ecclesiastical History of England, tr. A. M. Sellar (1907)","url":"https://www.gutenberg.org/ebooks/38326"},"rights":"pd","pd":"Sellar translation published 1907; Bede died 735"},{"id":"celt-macdonald-jan5","title":"From the Diary of an Old Soul, January 5","by":"George MacDonald","year":1880,"trad":["celtic","christian"],"denom":["scottish"],"type":"poem","occasion":["daily","peace"],"text":"Thy fishes breathe but where thy waters roll;\nThy birds fly but within thy airy sea;\nMy soul breathes only in thy infinite soul;\nI breathe, I think, I love, I live but thee.\nOh breathe, oh think, O Love, live into me;\nUnworthy is my life till all divine,\nTill thou see in me only what is thine.","note":"A seven line meditation from the Scottish poet whom Celtic Christian writers count among their own. Like a fish in water or a bird in the air, the soul lives in God.","voice":"brian","source":{"name":"A Book of Strife in the Form of the Diary of an Old Soul, George MacDonald (1880)","url":"https://www.gutenberg.org/ebooks/1953"},"rights":"pd","pd":"published 1880; MacDonald died 1905"},{"id":"celt-macdonald-jan29","title":"From the Diary of an Old Soul, January 29","by":"George MacDonald","year":1880,"trad":["celtic","christian"],"denom":["scottish"],"type":"poem","occasion":["dying","comfort"],"text":"Till Death has done with him? Ah, leave me then!\nAnd Death has done with me, oh, nevermore!\nHe comes, and goes, to leave me in thy arms,\nNearer thy heart, oh, nearer than before!\nTo lay thy child, naked, new-born again\nOf mother earth, crept free through many harms,\nUpon thy bosom, still to the very core.","note":"A seven line meditation from the Scottish poet whom Celtic Christian writers count among their own. Death as a passage that leaves the soul nearer to the heart of God.","voice":"brian","source":{"name":"A Book of Strife in the Form of the Diary of an Old Soul, George MacDonald (1880)","url":"https://www.gutenberg.org/ebooks/1953"},"rights":"pd","pd":"published 1880; MacDonald died 1905"},{"id":"celt-macdonald-mar2","title":"From the Diary of an Old Soul, March 2","by":"George MacDonald","year":1880,"trad":["celtic","christian"],"denom":["scottish"],"type":"poem","occasion":["evening","nature"],"text":"Gloriously wasteful, O my Lord, art thou!\nSunset faints after sunset into the night,\nSplendorously dying from thy window-sill:\nFor ever. Sad our poverty doth bow\nBefore the riches of thy making might:\nSweep from thy space thy systems at thy will:\nIn thee the sun sets every sunset still.","note":"A seven line meditation from the Scottish poet whom Celtic Christian writers count among their own. God gloriously wasteful with sunsets.","voice":"brian","source":{"name":"A Book of Strife in the Form of the Diary of an Old Soul, George MacDonald (1880)","url":"https://www.gutenberg.org/ebooks/1953"},"rights":"pd","pd":"published 1880; MacDonald died 1905"},{"id":"celt-macdonald-apr4","title":"From the Diary of an Old Soul, April 4","by":"George MacDonald","year":1880,"trad":["celtic","christian"],"denom":["scottish"],"type":"poem","occasion":["grief","hope"],"text":"I think I shall not ever pray for such;\nThy bliss will overflood my heart and brain,\nAnd I want no unripe things back again.\nLove ever fresher, lovelier than of old:\nHow should it want its more exchanged for much?\nLove will not backward sigh, but forward strain,\nOn in the tale still telling, never told.","note":"A seven line meditation from the Scottish poet whom Celtic Christian writers count among their own. Love that keeps growing forward, for those who long for what was lost.","voice":"brian","source":{"name":"A Book of Strife in the Form of the Diary of an Old Soul, George MacDonald (1880)","url":"https://www.gutenberg.org/ebooks/1953"},"rights":"pd","pd":"published 1880; MacDonald died 1905"},{"id":"celt-macdonald-sep27","title":"From the Diary of an Old Soul, September 27","by":"George MacDonald","year":1880,"trad":["celtic","christian"],"denom":["scottish"],"type":"poem","occasion":["comfort","evening"],"text":"On, eager, hungry, busy-seeking child,\nRise up, turn round, run in, run up the stair.\nFar in a chamber from rude noise exiled,\nThy father sits, pondering how thou dost fare.\nThe mighty man will clasp thee to his breast:\nWill kiss thee, stroke the tangles of thy hair,\nAnd lap thee warm in fold on fold of lovely rest.","note":"A seven line meditation from the Scottish poet whom Celtic Christian writers count among their own. The child running up the stair into the father's arms and rest.","voice":"brian","source":{"name":"A Book of Strife in the Form of the Diary of an Old Soul, George MacDonald (1880)","url":"https://www.gutenberg.org/ebooks/1953"},"rights":"pd","pd":"published 1880; MacDonald died 1905"},{"id":"celt-macdonald-nov8","title":"From the Diary of an Old Soul, November 8","by":"George MacDonald","year":1880,"trad":["celtic","christian"],"denom":["scottish"],"type":"poem","occasion":["daily","healing"],"text":"My God, I look to thee for tenderness\nSuch as I could not seek from any man,\nOr in a human heart fancy or plan:\nA something deepest prayer will not express:\nLord, with thy breath blow on my being's fires,\nUntil, even to the soul with self-love wan,\nI yield the primal love, that no return desires.","note":"A seven line meditation from the Scottish poet whom Celtic Christian writers count among their own. A prayer for a tenderness deeper than any human heart can give.","voice":"brian","source":{"name":"A Book of Strife in the Form of the Diary of an Old Soul, George MacDonald (1880)","url":"https://www.gutenberg.org/ebooks/1953"},"rights":"pd","pd":"published 1880; MacDonald died 1905"},{"id":"celt-macdonald-dec31","title":"From the Diary of an Old Soul, December 31","by":"George MacDonald","year":1880,"trad":["celtic","christian"],"denom":["scottish"],"type":"poem","occasion":["hope","season"],"text":"Go, my beloved children, live your life.\nWounded, faint, bleeding, never yield the strife.\nStunned, fallen-awake, arise, and fight again.\nBefore you victory stands, with shining train\nOf hopes not credible until they are.\nBeyond morass and mountain swells the star\nOf perfect love, the home of longing heart and brain","note":"A seven line meditation from the Scottish poet whom Celtic Christian writers count among their own. The old soul's farewell for the year: arise, and go on toward the star of perfect love.","voice":"brian","source":{"name":"A Book of Strife in the Form of the Diary of an Old Soul, George MacDonald (1880)","url":"https://www.gutenberg.org/ebooks/1953"},"rights":"pd","pd":"published 1880; MacDonald died 1905"},{"id":"celt-michael-white-steed","title":"Thou Gentle Michael of the White Steed","by":"Traditional, Hebridean (the shieling hymn)","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","catholic"],"denom":["scottish","hebridean"],"type":"hymn","occasion":["blessing","home","nature"],"text":"Thou gentle Michael of the white steed,\nWho subdued the Dragon of blood,\nFor love of God and the Son of Mary,\nSpread over us thy wing, shield us all!\nSpread over us thy wing, shield us all!\n\nMary beloved! Mother of the White Lamb,\nProtect us, thou Virgin of nobleness,\nQueen of beauty! Shepherdess of the flocks!\nKeep our cattle, surround us together,\nKeep our cattle, surround us together.\n\nThou Columba, the friendly, the kind,\nIn name of the Father, the Son, and the Holy Spirit,\nThrough the Three-in-One, through the Three,\nEncompass us, guard our procession,\nEncompass us, guard our procession.\n\nThou Father! Thou Son! Thou Holy Spirit!\nBe the Three-One with us day and night,\nOn the machair plain, on the mountain ridge,\nThe Three-one is with us, with His arm around our head,\nThe Three-One is with us, with his arm around our head.","note":"Sung on the midsummer move to the hill pastures, calling on Michael, Mary, Columba, and the Three; quoted from Carmichael by Fiona Macleod.","voice":"brian","source":{"name":"The Works of Fiona Macleod, vol. 4: Iona (1910)","url":"https://www.gutenberg.org/ebooks/37293"},"rights":"pd","pd":"Iona first published 1900; William Sharp (Fiona Macleod) died 1905; Carmichael died 1912"},{"id":"celt-herding-blessing","title":"From the Herding Blessing","by":"Traditional, Hebridean","tr":"Alexander Carmichael","year":1900,"trad":["celtic","christian","catholic"],"denom":["scottish","hebridean"],"type":"blessing","occasion":["blessing","nature","home"],"text":"I place this flock before me\nAs ordained by the King of the World,\nMary Virgin to keep them, to wait them, to watch them.\nOn hill and glen and plain,\nOn hill, in glen, on plain.\n\nFrom rocks, from snow-wreaths, from streams,\nFrom crooked ways, from destructive pits,\nFrom the arrows of the slim fairy women,\nFrom the heart of envy, the eye of evil,\nKeep us, Holy St. Bride.\n\nThe protection of God and Columba\nEncompass your going and coming,\nAnd about you be the milkmaid of the smooth white palms,\nBriget of the clustering hair, golden brown.","note":"Verses of the Hebridean blessing on the cattle going out to pasture, as Fiona Macleod quotes them from Carmichael.","voice":"brian","source":{"name":"The Works of Fiona Macleod, vol. 4: Iona (1910)","url":"https://www.gutenberg.org/ebooks/37293"},"rights":"pd","pd":"Iona first published 1900; William Sharp (Fiona Macleod) died 1905; Carmichael died 1912"},{"id":"celt-light-on-mountains","title":"My Soul Is With the Light on the Mountains","by":"Traditional, Hebridean","tr":"Fiona Macleod (William Sharp)","year":1900,"trad":["celtic","christian","catholic"],"denom":["scottish","hebridean"],"type":"prayer","occasion":["dying","evening","hope"],"text":"My soul is with the Light on the mountains,\nArchangel Micheil shield my soul!","note":"Two lines islanders said going to rest, setting out, or facing death.","voice":"brian","source":{"name":"The Works of Fiona Macleod, vol. 4: Iona (1910)","url":"https://www.gutenberg.org/ebooks/37293"},"rights":"pd","pd":"Iona first published 1900; William Sharp (Fiona Macleod) died 1905; Carmichael died 1912"},{"id":"celt-barra-fishermen","title":"The Barra Fishermen's Prayer","by":"Traditional, Hebridean","tr":"Fiona Macleod (William Sharp)","year":1900,"trad":["celtic","christian","catholic"],"denom":["scottish","hebridean"],"type":"prayer","occasion":["evening","comfort","nature"],"text":"O Father, Son, and Holy Ghost! O Holy Trinity, be with us day and night. On the crested wave as on the mountain-side! Our Mother, Holy Mary Mother, has her arm under our head; our pillow is the arm of Mary, Mary the Holy Mother.","note":"A verse sung by Barra fishermen, given in prose: our pillow is the arm of Mary.","voice":"brian","source":{"name":"The Works of Fiona Macleod, vol. 4: Iona (1910)","url":"https://www.gutenberg.org/ebooks/37293"},"rights":"pd","pd":"Iona first published 1900; William Sharp (Fiona Macleod) died 1905; Carmichael died 1912"},{"id":"celt-all-through-night","title":"All Through the Night","by":"Traditional Welsh air (Ar Hyd y Nos), English words by Harold Boulton","year":1884,"trad":["celtic","all"],"denom":["welsh"],"type":"song","occasion":["evening","peace","birth","dying"],"text":"Sleep my child and peace attend thee,\nAll through the night;\nGuardian angels God will send thee,\nAll through the night;\nSoft the drowsy hours are creeping,\nHill and vale in slumber sleeping,\nI my loving vigil keeping,\nAll through the night.","note":"The Welsh lullaby, also sung softly at bedsides and vigils; spoken here, with the words only.","voice":"brian","source":{"name":"Ar Hyd y Nos, English words by Sir Harold Boulton (1884)","url":"https://en.wikipedia.org/wiki/Ar_Hyd_y_Nos"},"rights":"pd","pd":"traditional; standard wording; English words by Harold Boulton published 1884; Boulton died 1935"},{"id":"celt-g-circle-bedside","title":"A Circling Prayer for the Bedside","by":"Grow With Grounded","year":2026,"trad":["celtic","christian"],"type":"blessing","occasion":["dying","healing","comfort"],"text":"Circle this bed, O Sacred Three.\nKeep peace within, keep worry without.\nKeep comfort within, keep pain without.\nKeep love within, keep loneliness without.\n\nFather at the head,\nSon at the feet,\nSpirit at each side,\nand the whole household of heaven\nclose around this resting place,\nthis night and every night.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-circle-home","title":"A Circling Prayer for the Home","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["home","blessing"],"text":"Circle this house, O Love that made us.\nCircle the door and the window,\nthe table and the hearth,\nthe beds where we rest\nand the paths where we walk.\n\nKeep kindness within, keep harshness without.\nKeep laughter within, keep strife without.\nHold each one here\nin the circle of Your love,\nmorning, noon, and night.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-circle-journey","title":"A Circling Prayer for a Journey","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["blessing","hope"],"text":"Circle me on the road, O God of the way.\nCircle the path before me\nand the miles behind me,\nthe hills to climb and the rivers to cross.\n\nKeep courage within, keep fear without.\nKeep a steady hand and a quiet heart.\nBring me safely there,\nand bring me safely home.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-circle-child","title":"A Circling Prayer for a Child","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["blessing","birth","home"],"text":"Circle this little one, O Gentle Shepherd.\nCircle the cradle and the climbing tree,\nthe schoolroom and the playing field.\n\nKeep wonder within, keep harm without.\nKeep joy within, keep sorrow far.\nHold this child as the hills hold the morning,\ngently, and all the day long.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-hearth-morning","title":"A Hearth Blessing for the Morning","by":"Grow With Grounded","year":2026,"trad":["celtic","christian"],"type":"blessing","occasion":["morning","home"],"text":"I lift the fire this morning\nin the name of the Maker of light,\nin the name of the Son who warms the heart,\nin the name of the Spirit who kindles every good thing.\n\nMay the warmth of this hearth\nreach every one who comes to it,\nthe friend and the stranger,\nthe weary and the glad,\nand may the fire of love in me\nburn bright and steady all this day.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-hearth-night","title":"A Hearth Blessing for the Night","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["evening","home"],"text":"I bank the fire for the night\nand give the embers into the keeping of God.\nThree for the hearth, three for the house, three for the household.\nMay the seed of the fire rest safe till morning,\nmay every heart in this house rest safe till morning,\nand may we rise to a warm hearth\nand a new day of grace.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-threshold","title":"A Threshold Blessing","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["home","blessing"],"text":"Bless this threshold, God of every coming and going.\nBless the feet that cross it in gladness\nand the feet that cross it in sorrow.\nBless the one who knocks and the one who opens.\nMay all who enter here find welcome,\nand all who leave here carry peace.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-new-home","title":"A Blessing for a New Home","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["home","blessing","celebration"],"text":"Bless this new home from floor to rafter,\nfrom hearth to doorstep,\nfrom the first box carried in\nto the last light turned out tonight.\nBless the walls that will hear our laughter,\nthe table that will hold our meals,\nthe rooms that will hold our rest.\nMay this house become a home,\nand this home a place of peace.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-newborn","title":"A Blessing for a Newborn","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["birth","blessing"],"text":"A blessing on your breath, little one,\na blessing on your small strong heart,\na blessing on your hands that will reach,\na blessing on your feet that will wander and return.\n\nThe warmth of the sun for you,\nthe shelter of the trees for you,\nthe song of the birds for you,\nand the love of all who gather here\naround you all your days.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-first-day","title":"A Blessing for a Child's First Day","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["blessing","hope"],"text":"Go gently into this new day, dear one.\nMay your teachers be kind,\nmay your friends be true,\nmay your questions be welcomed,\nand may you come home tonight\nwith a story to tell and a heart full of courage.\nWe are proud of you, and we are right here.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-wedding","title":"A Wedding Blessing in the Celtic Spirit","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["wedding","blessing","celebration"],"text":"May the sun bless your mornings together,\nand the moon your evenings.\nMay the rain keep your garden green\nand the wind carry your laughter.\nMay your home be warm, your table full,\nyour door wide to friends.\nAnd may the love that brought you here today\ngrow deeper with every season,\nlike a tree rooted by the water.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-joining-hands","title":"A Blessing for Two Joining Hands","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["wedding","blessing"],"text":"These are the hands that will hold yours in the good years.\nThese are the hands that will hold yours in the hard years.\nThese are the hands that will work beside yours,\nbuild with yours, and reach for yours in the dark.\nAs these hands are joined today,\nmay your lives be joined in faithfulness and joy,\nbound by love, gladly given,\nfor all the days to come.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-anniversary","title":"An Anniversary Blessing","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["wedding","celebration","gratitude"],"text":"For every morning you have shared, thanks be.\nFor every meal, every road, every season, thanks be.\nFor the love that has weathered storms and basked in sun, thanks be.\nMay the years ahead be as rich as the years behind,\nand may you keep finding each other new.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-soul-leaving","title":"A Blessing for the Soul's Leaving","by":"Grow With Grounded","year":2026,"trad":["celtic","christian"],"type":"blessing","occasion":["dying","comfort"],"text":"Go gently now, dear soul.\nGo in the peace of the Father who made you,\nin the peace of the Son who walks beside you,\nin the peace of the Spirit who breathes with you still.\n\nMay Michael meet you at the shore,\nmay Brigid wrap you in her mantle,\nmay Mary lead you by the hand,\nand may all who loved you and went before\nbe waiting at the open door\nof the house where you are welcome home.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]},{"id":"celt-g-last-breath","title":"At the Last Breath","by":"Grow With Grounded","year":2026,"trad":["celtic","all"],"type":"blessing","occasion":["dying","grief"],"text":"Breath of life, we give thanks for this breath,\nfor every breath this dear one has taken,\nfrom the first cry to this quiet ending.\nNow the breath returns to the One who gave it.\nRest now, beloved, held in love.\nGo in peace.","note":"Written by Grounded in the spirit of the Celtic tradition, for spoken use at home, at a bedside, or in a ceremony.","voice":"brian","source":{"name":"Grow With Grounded, written for the Readings Library","url":"https://growwithgrounded.com/readings.html"},"rights":"grounded","pd":"Grounded's own words, written in the spirit of the Celtic tradition","denom":[]}];
